quests[35014] = { id = 35014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenmondflor", description = "Uns gehen die Optionen aus.\n\nIch werde in den Flor gehen, um herauszufinden, was vor sich geht. Ich treffe Euch im Innern.\n\nViel Glück, {class}.", sourceObjective = "Trefft Rangari Arepheon im Klingenmondflor.", completion = "Gut, Ihr habt es geschafft. Ich brauche Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35015] = { id = 35015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trächtiger Genesaurier", description = "Das ist wirklich übel. Genau hier mitten im Flor sprießt ein Genesaurier.\n\nDas ist seit über dreihundert Jahren der erste Genesaurier, der in Draenor das Licht der Welt erblickt.\n\nKein Wunder, dass sich die Botani in letzter Zeit so merkwürdig verhalten. Sie schleppen jede Menge Kadaver an, um diese Monstrosität zu füttern.\n\nWir müssen diese Abscheulichkeit vernichten, bevor sie noch weiter wächst. Ist diese Bestie erst einmal ausgewachsen, kann sie nichts und niemand mehr aufhalten.", sourceObjective = "Tötet den Genesaurier.", completion = "Das war knapp.\n\nWenn dieser Genesaurier weiter gewachsen wäre, hätten wir eine ganze Armee benötigt, um ihn zur Strecke zu bringen.\n\nVielen Dank für all Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35016] = { id = 35016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einführungskurs zum Schädelsammeln", description = "Meine Jäger hat es alle erwischt, also werdet Ihr nun mein Jagdrudel sein.\n\nFindet ihre Leichen und sammelt ihre Schädel ein. Ich wähle dann, welche zu ehren sind und welche zu schmähen. So ist es Brauch.\n\nAußerdem sehe ich mich um, was für Schädel hier sonst noch zu finden sind.", sourceObjective = "Sammelt die Schädel von 5 toten Schädelsammlern ein.", progress = "Habt Ihr Angst, Euch die Hände schmutzig zu machen? Vor ihren reglosen Körpern braucht Ihr Euch wirklich nicht zu fürchten.", completion = "Der rote Schleim bedeckt einfach alles, sogar die Schädel meiner Jäger! Aber aus Euch mach ich trotzdem einen richtigen Schädelsammler, wartet es nur ab!", sourceObjectiveStatus = "unverified-source-field" }
quests[35017] = { id = 35017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache des Schädelsammlers", sourceObjective = "Tötet 7 Fungusschlinger.", completion = "Pah! Wenn er so stark wäre, dann wäre er noch lebendig. Trotzdem ist es gut, dass Ihr ihm Ehre erwiesen habt. Konntet Ihr vielleicht auch seinen Schädel bergen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35018] = { id = 35018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Teufelsborke" }
quests[35019] = { id = 35019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für die Schlacht", description = "Hier oben gibt es keine Möglichkeit, sich zu verstecken. Wir müssen in Bewegung bleiben, und dafür müssen wir mitten durch das Herz der Eisernen Horde.\n\nHöchste Zeit, dass wir diese unbewaffneten Gefangenen zu einer Armee machen.", sourceObjective = "Erbeutet 30 Schwarzfelswaffen.", progress = "Die Gefangenen sind nicht weniger mutig als Ihr oder ich, {name}. Gebt Ihnen Waffen und einen Funken Hoffnung, und schon kämpfen sie wie die Löwen.", completion = "Gut gemacht, {name}.\n\nDoch steckt Eure Waffe noch nicht fort – jetzt kommt erst die RICHTIGE Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35021] = { id = 35021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Kapsel", description = "Diese Kapsel ähnelt denen, die auf oder bei den Körpern hier in der Gegend wachsen, allerdings pulsiert sie seltsam. Grulkor könnte eine Erklärung dafür haben.", sourceObjective = "Bringt die leuchtende rote Kapsel zu Grulkor im Blutroten Sumpf.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr da? Lasst mich sehen, ob sie einen Schädel hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[35022] = { id = 35022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhellen der Dunkelheit", description = "Die Geister meiner Vorfahren wurden seit jeher von dem Berg Oshu'gun angezogen. Nun spüre auch ich den lockenden Ruf tief in meiner Seele... aber irgendetwas stimmt nicht.\n\nDie uns rufende Präsenz ist finster geworden, bedrohlich. Sie verschlingt die Seelen der Toten, die Seelen meiner Vorfahren, {name}.\n\nDem muss Einhalt geboten werden.\n\nNehmt die Geisterfackel und entzündet damit die zeremoniellen Scheiterhaufen auf dem Ahnengrund.\n\nDie heiligen Flammen werden dazu beitragen, die rastlosen Geister, die in die Leere gezogen werden, zu beruhigen.", sourceObjective = "Entzündet mit der Geisterfackel die zeremoniellen Scheiterhaufen auf dem Ahnengrund.", completion = "Durch die Flammen der Geisterfackel, die nun auf den Scheiterhaufen lodern, sind die Geister meiner Ahnen vor dem Ruf der Leere aus dem Inneren von Oshu'gun gefeit.\n\nAllerdings muss noch mehr unternommen werden, damit die Geister endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35023] = { id = 35023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos der Vergangenheit", description = "Wenn ein Geist von der Leere verschluckt wird, bleibt nichts als ein Echo seiner Seele zurück.\n\nDiese Echos können weder im physischen noch im spirituellen Sinne des Wortes als \"lebendig\" gelten. Solch ein Echo ist nichts weiter als der verzerrte Widerhall des Leids, das die Seele erleidet, wenn sie verschlungen wird.\n\nWenn man den Echos nicht Einhalt gebietet, fallen sie über die Lebenden her und schrecken die Geister der Toten aus ihren Gräbern auf.\n\nDamit auf dem Ahnengrund Frieden einkehren kann, müssen die Echos zur Ruhe gebettet werden.", sourceObjective = "Vernichtet 8 gepeinigte Echos.", completion = "Trauert nicht um die verderbten Echos der Toten. Sie sind nur verzerrte Spiegelungen einst edler Geister.\n\nTrauert lieber um den Verlust der Seelen, die von der finsteren Leere verschlungen werden, die tief in Oshu'gun heranwächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[35024] = { id = 35024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golmash Höllschrei", description = "Jene, die bei brutalen Kämpfen sterben, bleiben vor Unruhe oft in der Geisterwelt gefangen. So war es auch mit Golmash, dem Vater von Grommash Höllschrei.\n\nNoch als ihn die Kiefer eines riesigen Gronns zermalmten, fand Golmash die Kraft, seine Axt Blutschrei tief im Auge des Monsters zu versenken. Als sie stürzten, war es der Gronn, der zuerst starb.\n\nDas ist ein Tod, wie ihn sich jeder Krieger des Kriegshymnenklans wünscht. Nur wenigen ist er vergönnt. Trotzdem findet Golmashs mächtiger Geist keine Ruhe und treibt sogar die anderen Geister in Aufruhr.\n\nBringt seiner mächtigen Seele Frieden, {name}.", sourceObjective = "Besiegt den Geist von Golmash Höllschrei.", completion = "Golmash war zu seinen Lebzeiten ein großer Krieger.\n\nNur wenige Orcs wurden von ihren Klans so verehrt und von ihren Feinden so gefürchtet wie der große Riesentöter... der Ursprung des Namens Höllschrei. Nachdem der mächtige Geist von Golmash Höllschrei endlich Ruhe gefunden hat, ist der Ahnengrund wieder ein Ort des Friedens und der Andacht.\n\nWir werden Euch ewig dankbar sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35025] = { id = 35025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben Gesellschaft", description = "Fremdling, ich habe Soldaten der Eisernen Horde in der Nähe gesehen.\n\nSogar für ihre Verhältnisse ist es sehr tollkühn, sich in eine so gefährliche Gegend vorzuwagen.\n\nWenn Ihr nichts unternehmt, könnten sie sicher zu einer Bedrohung für unser Lager werden.", sourceObjective = "Erkundet das Lager der Eisernen Horde im Schwefelbecken.", completion = "Vielen Dank. Ich stehe in Eurer Schuld.\n\nDie Eiserne Horde hat sich heute einen gefährlichen Feind geschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35026] = { id = 35026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Weg der Besserung", description = "Nisha wird wieder.\n\nSie ist geschwächt nach allem, was sie durchstehen musste. Sie benötigt Wasser und Ruhe.\n\nIch bringe sie in mein Lager und mache es ihr bequem.\n\nKönnt Ihr uns etwas Wasser dort hinbringen?", sourceObjective = "Holt 100 erfrischendes Wasser von Dampfzornelementaren.", progress = "<Nisha hebt den Kopf.>", completion = "<Nisha trinkt etwas Wasser.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35027] = { id = 35027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Die Toten waren wohl die Starken. Die Schwachen wandeln umher und töten jeden, der es wagt, den Sumpf zu betreten.\n\nEs fühlt sich nicht richtig an... sie zu töten... aber sie sind wertlos und stehen uns im Weg. Tötet diese herumtorkelnden Narren, damit wir weiter in den Sumpf vordringen können!", sourceObjective = "Tötet 6 pilzbedeckte Schlurfer.", completion = "Ihr braucht zu lange! Etwas tiefer im Sumpf ruft uns. Was auch immer es ist, ich werde mir seinen Schädel holen oder bei dem Versuch sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35028] = { id = 35028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren von Krikka und Vakora" }
quests[35029] = { id = 35029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Fungus", description = "Hier stinkt es, und ich höre ein Flüstern.\n\nIch spüre, dass es eine Verbindung zwischen den Pflanzen und den Monstern der Gegend gibt. Sie scheinen sich für eine besondere Art von Pilzen zu interessieren.\n\nBesorgt mir welche davon! Ich... brauche... sie.", sourceObjective = "Sammelt 5 leuchtende Pilze ein.", progress = "Wo bleiben meine Pilze?", completion = "Jaaa, sie riechen... wunderbar. Sie werden mir dabei helfen, die Macht des Sumpfes zu verstehen und für mich zu beanspruchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35030] = { id = 35030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Ernte", description = "Die größeren Monster sind der Schlüssel zu meinem Schicksal, ich spüre es. Die Kapseln, die auf ihnen wachsen, sind noch größer. Bringt mir davon auch noch welche. Sie werden... schon bald... nützlich sein.", sourceObjective = "Bringt Grulkor 3 Sporenkapseln von den Fungusstampfern.", progress = "Ich brauche noch mehr von den Kapseln! Viel mehr!", completion = "Sie werden mir helfen. Ich muss sie essen, um mir ihre Kraft einzuverleiben. Bald haben wir unser Ziel erreicht, {name}, ich spüre es.", sourceObjectiveStatus = "unverified-source-field" }
quests[35031] = { id = 35031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine beherzte Suche", sourceObjective = "Untersucht die mysteriöse Präsenz im Blutroten Sumpf.", completion = "Wir sind fast da, ich kann es beinahe berühren! Wir müssen noch tiefer vordringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35032] = { id = 35032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten in der Pein", description = "Rulkans Geschenk an Euch, das Fragment der Pein, wird es Euch ermöglichen, die Festung ungehindert zu betreten. Begebt Euch die Treppe hinauf zum Eingangstor und benutzt dort das Fragment, um das Areal zu betreten.\n\nSobald Ihr im Inneren seid, haltet die Augen nach den drei Altären offen, die die magische Barriere um die Feste herum aufrechterhalten.\n\nZerstört diese Runen, damit Yrel und ich zu Euch stoßen können, um gemeinsam nach Ner'zhul zu suchen.", sourceObjective = "Benutzt das Fragment der Pein am Haupteingang. Zerstört dann das Mal der Dunkelheit, das Mal des Schattens und das Mal der Pein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35033] = { id = 35033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Gorgrond", description = "Gorgrond ist eine der urtümlichsten Gegenden von ganz Draenor.\n\nNur die fähigsten Rangari wagen sich so tief in die Wildnis.\n\nWir wollen zu ihrem Lager. Falls Ihr schon vorgehen wollt, es liegt entlang dieses Pfades auf der rechten Seite.\n\nMaraad und ich werden Euch in Kürze folgen. Wir haben noch einige logistische Fragen zu klären, bevor wir hier aufbrechen.", sourceObjective = "Folgt dem Wildwuchsbett bis zu Naielles Wacht.", completion = "Ihr habt einen äußerst unglücklichen Zeitpunkt für Euren Besuch gewählt, werter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[35035] = { id = 35035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saatbringer schlechter Nachrichten", description = "Wenn diese Saatträger getötet werden, überleben ihre Samen. Sie wachsen heran zu neuen Saatbringern – und zwar nicht im Verlauf mehrerer Jahre, sondern innerhalb weniger Stunden.\n\nWenn Ihr die Überreste hier zurücklasst, wird Euer Lager bald überrannt werden.\n\nVerbrennt sie, <Fremder/Fremde>, wenn Ihr wollt, dass das Lager bestehen bleibt.", sourceObjective = "Verbrennt 5 Leichen von Saatbringerurtumen.", completion = "Seht sie brennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35036] = { id = 35036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehört der zu Euch?", description = "Den hab ich in der Nähe herumlungernd gefunden. Er behauptet, ein Verbündeter von Euch zu sein.\n\nIst das wahr? Oder soll ich ihn langsam über offenem Feuer kochen?", sourceObjective = "Sprecht mit Rexxar und bürgt für den Knochigen Xais.", completion = "Dieser Halborc hat mir die Zehen verbrannt!", sourceObjectiveStatus = "unverified-source-field" }
quests[35037] = { id = 35037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaum zu zerbrechen", description = "Schreie und Knurren hallen unten in der Schlucht wider... mehr noch als sonst.\n\nIch wage es noch nicht, Nisha hier alleine zu lassen.\n\nWürdet Ihr diesen Geräuschen nachgehen, {name}?", sourceObjective = "Erkundet das Lager der Eisernen Horde in Malmzahns Ende.", completion = "Sie versklaven Gronn? Das Problem ist größer, als es den Anschein hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[35038] = { id = 35038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Knochigen Xais?", description = "Schön zu sehen, dass Eure Knochen noch intakt sind, {name}. Xais' ebenfalls.\n\nAls Ihr zur Schlucht aufgebrochen wart, kam Xais, um seine Dienste anzubieten. Xais lässt Euch nicht alle Schädel nehmen!\n\nXais wird die mächtige Magie der Geister mit Euch teilen, die sein Klan seit vielen Generationen weiterreicht. Während Xais Vorbereitungen trifft, müsst Ihr die Zutaten sammeln.\n\nZunächst brauchen wir Kristalle aus den Überresten von Gorenleichen. Diese findet Ihr in der Schlucht.", sourceObjective = "Sammelt 25 Gorenkristalle von Langzahnschlingern.", progress = "Wir Lachenden Schädel haben immer ein paar schmutzige Tricks hinter unseren Masken.", completion = "Ja... ihre Knochen brauchen wir nicht, aber ihre Kristalle schon.", sourceObjectiveStatus = "unverified-source-field" }
quests[35040] = { id = 35040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Sumpfs", description = "Wenn mich die Bäume hier doch nur nicht ständig so anschreien würden, könnte ich mich besser konzentrieren. Egal, es sind bloß Bäume.\n\nDieser Ort ist aufgebraucht, aber nun spüre ich eine viel stärkere Präsenz tiefer im Sumpf. Dort werde ich jetzt hingehen und nehmen, was rechtmäßig mir gehört!\n\nDann teile ich es... mit allen...", sourceObjective = "Dringt mit Grulkor tiefer in den Blutroten Sumpf ein und kümmert Euch um das, was Ihr vorfindet.", completion = "Grulkor muss verrückt gewesen sein, dass er dachte, die Kräfte dieser Pilze nutzen zu können, aber verrückt sind ja die Meisten des Lachenden Schädels.\n\nImmerhin war es keine völlige Zeitverschwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[35041] = { id = 35041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So ein Xais!", description = "Es ist vollbracht.\n\nMit dieser Verzauberung könnt Ihr Euch nicht nur frei unter den Goren bewegen, sondern Euch auch WIE sie bewegen.\n\nEure Reisen durch Gorgrond sind jetzt einfacher. Ihr habt Zugang zu Orten, die sonst unmöglich zu erreichen wären.\n\nXais' Ahnen haben das so gemacht.", sourceObjective = "Benutzt die Gorenverkleidung, um Gegenden in Gorgrond zu erkunden.", progress = "Was hat der Orc Euch bloß getan?!", completion = "Es ist gut, dass Ihr noch all Eure Sinne beisammen habt. Ihr... habt doch Eure Sinne beisammen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[35044] = { id = 35044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cordana beschwören" }
quests[35045] = { id = 35045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Erinnerung an Ared", description = "Mein Meister ist ins Licht gegangen, doch ich werde seine Arbeit fortsetzen.\n\n<Miall sieht Ared an.>\nShanai ortar, Ared.\n\nIch werde seine Leiche nach Auchindoun bringen lassen. Zeigt mir zuerst einmal Euren Artillerieturm.", sourceObjective = "Sprecht mit Miall in Fort Wrynn in Talador.", completion = "Dies ist ein wunderschönes und gut ausgestattetes Gebäude. Vielen Dank, dass Ihr mir erlaubt, hier zu arbeiten.\n\nIch bin mir sicher, dass ich hier das Vermächtnis meines Meisters weiterführen kann. Ihr werdet es nicht bereuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35047] = { id = 35047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs Tracking" }
quests[35049] = { id = 35049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägewerk" }
quests[35050] = { id = 35050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Rangari", description = "Viele unserer Rangari werden noch vermisst. Anscheinend haben die Gefolgsleute von Iyu Gefangene genommen.\n\nWir werden die Gegend weiter nach Überlebenden absuchen.\n\nDerweil könntet Ihr dem Wildwuchsbett nach Westen in Richtung Hochpass folgen und nach Lebenszeichen unserer Rangarikameraden Ausschau halten.\n\nUnsere Leute sind zäh. Die bringt nichts so schnell um! Womöglich findet Ihr mehr Überlebende, als Ihr erwartet. Sagt ihnen, sie sollen bei der Straße warten. Wir kommen nach, sobald diese... Zwergenkreatur... sein mechanisches Gefährt repariert hat.", sourceObjective = "Findet Rangari Rajess, Rangari Kolaan und Rangari Jonaa.", completion = "Diese Rangari sind hartgesottene Überlebenskünstler. Ich wusste doch, dass sie sich nicht einfach geschlagen geben würden.\n\nIch danke Euch, {name}! Ihr habt uns eine große Ehre erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35051] = { id = 35051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierturm vollendet" }
quests[35055] = { id = 35055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maulwurfmaschinen auf Abwegen", description = "Nur wenige kennen den Schwarzfelsklan besser als die Dunkeleisenzwerge.\n\nDeshalb haben wir nach den Geschehnissen in Tanaan ein paar Maulwurfmaschinen nach Gorgrond geschickt, um einen Horchposten einzurichten und sie zu überwachen.\n\nMeine eigene Maulwurfmaschine ist leider ganz schön vom Weg abgekommen, sodass ich von den anderen getrennt wurde. Allerdings habe ich schon bald danach herausgefunden, dass sich alle anderen Maschinen ebenso verirrt haben.\n\nLaut den Anzeigen meines Panzers ist eine Maulwurfmaschine westlich von hier an die Oberfläche gekommen.\n\nKönntet Ihr sie suchen, während wir diesen Panzer wieder in Gang bringen?", sourceObjective = "Findet die vermisste Maulwurfmaschine.", completion = "Gut, einer weniger und noch ungefähr ein Dutzend übrig. Wir sollten hier einen Stützpunkt errichten. Es klingt, als würden wir hier eine Weile festhängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35056] = { id = 35056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag - Horned Skull" }
quests[35057] = { id = 35057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette Erfahrungsbonus: Frostfeuer" }
quests[35058] = { id = 35058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mysteriöse Fläschchen", description = "Die wirbelnde Flüssigkeit in dem Fläschchen besitzt eindeutig ein starkes alchemistisches Potential, doch mit Euren Fähigkeiten vermögt Ihr es nicht zu ergründen.\n\nIhr habt gehört, dass einer der Steinzahnflüchtlinge in Eurer Garnison in der Alchemie von Draenor bewandert zu sein scheint. Womöglich kann er Euch weiterhelfen?", sourceObjective = "Sprecht mit Lo'nash in Eurer Garnison.\n\nBereitgestellter Gegenstand:", completion = "Ah, wie ich sehe, habt Ihr ein Erzeugnis der Alchemie von Draenor gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35059] = { id = 35059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlang des Flusses", description = "Verteidigerin Yrel ist mit dem Großteil unserer Truppen gen Norden gezogen. Sie errichtet einen Vorposten am Himmelsweisenfluss.\n\nSie wird sich freuen zu erfahren, dass wir bereit sind, gegen Grommashar zu ziehen.\n\nAußerdem könnte sie gegen die Orcs vom Kriegshymnenklan in Lok-rath sicher Eure Hilfe gebrauchen.", sourceObjective = "Sprecht mit Verteidigerin Yrel in Yrels Wacht.", completion = "Es tut gut, Euch zu sehen, Kommandant. Als wir hörten, dass die Garnisonskarawane zerstört wurde...\n\nNun ja, ich befürchtete das Schlimmste.\n\nWelche Neuigkeiten bringt Ihr von der Telaaristation?", sourceObjectiveStatus = "unverified-source-field" }
quests[35060] = { id = 35060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitulationsbedingungen", description = "Ob Ihr es glaubt oder nicht, es gibt eine gute Nachricht: Wir haben Lok-rath bereits eingenommen.\n\n<Die Verteidigerin strahlt vor Stolz.>\n\nUnsere Soldaten haben viele Krieger des Kriegshymnenklans gefangen genommen, auch ihren Anführer, Uruk Feindspalter.\n\nDie Ehre, seine Kapitulation zu akzeptieren, ist ganz die Eure. Sie warten drinnen auf Euch, Kommandant.", sourceObjective = "Sprecht mit Uruk Feindspalter in Lok-rath.", completion = "Kommandant {name}.\n\n\n\nKapitulationsbedingungen? Hmmm... lasst mich nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35061] = { id = 35061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz von Lok-rath", description = "Glaubt Ihr wirklich, der Kriegshymnenklan wäre so leicht zu besiegen?\n\n<Ein kratzendes Geräusch wie von einem Messer auf einem Seil ist zu hören.>\n\nIch bin Eure jämmerliche Allianz schon jetzt leid, und dabei seid Ihr gerade erst in mein Heimatland eingefallen.\n\n<Das Geräusch wird deutlicher, während Euch Uruk Feindspalter in die Augen blickt.>\n\nEs gibt keine Kapitulation. Der Kriegshymnenklan unterwirft sich niemandem!", sourceObjective = "Tötet Uruk Feindspalter.", completion = "Schade, aber ich bin froh, dass Ihr der Falle lebend entkommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[35062] = { id = 35062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok-rath ist gesichert", description = "Da ihr Anführer tot ist, wird der Rest des Kriegshymnenklans leichter zu besiegen sein.\n\nSobald das erledigt ist, ziehe ich unsere Soldaten aus Lok-rath ab und marschiere nach Grommashar.\n\nWenn Ihr zur Telaaristation zurückkehrt, könntet Ihr dann bitte D'kaan informieren?", sourceObjective = "Sprecht mit Rangari D'kaan in der Telaaristation.", completion = "Wäret Ihr nicht nach Lok-rath gegangen, hätten unsere Truppen eine schreckliche Niederlage erlitten.\n\nEs tut mir leid, dass Euch eine Falle gestellt wurde. Ich vermute, Ihr habt inzwischen einen gewissen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[35063] = { id = 35063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen einen Außenposten", description = "Kommandant, wir haben jetzt genug Material zum Bau eines Außenpostens gesammelt, der unsere Mission gegen die Eiserne Horde unterstützen kann.\n\nWie wollen wir fortfahren?\n\nEin Sägewerk wäre hilfreich, um Ressourcen aus der dichten Überwucherung im Süden zu gewinnen und um mit den Pflanzenmonstrositäten fertigzuwerden, die sie verteidigen.\n\nAndererseits würde uns eine Übungsarena genau die brutalen Truppen bereitstellen, die wir für unser Vorankommen in der Magnaroneinöde im Norden benötigen würden.\n\nTrefft Eure Entscheidung am Zeichentisch, wenn Ihr so weit seid.", sourceObjective = "Entscheidet Euch am Zeichentisch für den Bau eines Sägewerks oder einer Übungsarena.", completion = "Eine gute Wahl. Ich sag Euch was, Ihr sorgt dafür, dass das Gebäude hier voll einsatzbereit ist, dann versuche ich, die Baupläne auf die Gegebenheiten Eurer Garnison zu übertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35064] = { id = 35064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsarena" }
quests[35065] = { id = 35065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ernter ist gekommen", description = "Das passiert, wenn man einem Genesaurier in die Quere kommt. Und wo ein Genesaurier ist, sind Botani nicht weit.\n\nIch habe gesehen, wie einer davon in unsere Schutzhöhle auf der nördlichen Seite des Lagers gekrochen ist.\n\nEr treibt die Schotlinge dazu an, die Leichen unserer gefallenen Brüder einzusammeln. Dem muss Einhalt geboten werden!\n\nIch bin noch damit beschäftigt, unsere Verwundeten zu versorgen und Vorräte für unsere Reise zusammenzusuchen.\n\nWenn Ihr ernsthaft <ein Held/eine Heldin> seid, geht in die Höhle und tötet diesen Botani!", sourceObjective = "Tötet Ernter Ommru.", completion = "Ich will gar nicht daran denken, was der Botani mit den Leichnamen unserer Gefallenen vorhatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[35066] = { id = 35066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerammonit", description = "Wir müss'n den Garnisonsteich mit einheimischen Fischen bevölkern. Wie wär's wenn Ihr in den Gewässern des Frostfeuergrats nach geeigneten sucht? Wenn Ihr welche habt, müsst Ihr sie aufschneiden und nach Eiern seh'n.", sourceObjective = "Mak'jin möchte, dass Ihr in Frostfeuergrat die Eier von 10 Feuerammoniten einsammelt.", progress = "Beißen sie?", completion = "Die sind goldrichtig, {name}! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[35067] = { id = 35067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt die Kriegsmaschinen zum Schweigen", description = "Die Eiserne Horde hat Lok-rath mit Kriegsmaschinen aus dem Eisenfausthafen versorgt. Sie werden nicht lange brauchen, um Yrels Wacht dem Erdboden gleichzumachen.\n\nJemand muss die Kriegsmaschinen ausschalten!", sourceObjective = "Zerstört 3 Kriegsmaschinen der Eisernen Horde.", completion = "Danke, Kommandant! Ich war sicher, wir wären erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35068] = { id = 35068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht kapitulieren will...", description = "Das ist das Rückgrat der Armee, die wir gegen Garrosh Höllschrei und Grommashar schicken wollen.\n\nWenn sie nicht kapitulieren, bleibt uns keine andere Wahl, als den Kriegshymnenklan zu eliminieren.", sourceObjective = "Tötet 10 feindliche Soldaten in Lok-rath.", completion = "Bedauerlich, doch ich habe Verständnis für den Stolz des Kriegshymnenklans. Ich würde auch niemals kapitulieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35069] = { id = 35069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken von Nagrand", description = "<Hier liegt der bleiche Körper eines gefallenen Soldaten. Blutige Spuren führen von der Leiche zu dem Höhleneingang im Norden.>\n\n<Dem Heulen und den Spuren eines Gemetzels vor der Höhle nach zu urteilen, muss sich etwas wahrhaft Furchterregendes dort drinnen aufhalten.>", sourceObjective = "Nehmt Euch Shagors Halsband von Shagor.", progress = "Kommandant. Wie kann ich Euch zu Diensten sein?", completion = "Das ist das Halsband des Tieres? Ich habe sein Heulen bis hierher gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[35070] = { id = 35070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet es ab!", description = "Grabende Kreaturen dieser Gegend, bekannt als \"Goren\", haben sich in unsere Kristallminen gegraben. Von unserem Erlebnis bei den Toren ausgehend, vermute ich, dass mein experimenteller Resonanzkristall die einheimische Tierwelt zur Raserei bringt.\n\nBetretet die Grabung von Elodor im Norden und deaktiviert den defekten Resonanzkristall!\n\nAber seid vorsichtig – meine Erdarbeiter melden, dass die Mine voll von diesen Biestern ist.", sourceObjective = "Deaktiviert den defekten Resonanzkristall in der Grabung von Elodor.", completion = "Ausgezeichnet. Ich werde einige Friedensbewahrer entsenden, die sich der restlichen Probleme annehmen.\n\nExarchin Naielle hat möglicherweise recht – vielleicht bin ich zu aggressiv darin, unsere Technologie an diese Welt anzupassen. Doch ich werde nicht aufhören. Unsere Zivilisation muss sich weiterentwickeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[35071] = { id = 35071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kieferloser Schleicher", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Gorgrond nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Mak'jin möchte, dass Ihr in Gorgrond die Eier von 10 kieferlosen Schleichern einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[35072] = { id = 35072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicker Schläfer", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Nagrand nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Mak'jin möchte, dass Ihr in Nagrand die Eier von 10 dicken Schläfern einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[35073] = { id = 35073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinder Seestör", description = "Wir müssen den Teich der Garnison mit einheimischen Fischen füllen. Ich möchte, dass Ihr die Gewässer im Schattenmondtal nach Fischen absucht, mit denen wir sie bevölkern können. Sobald Ihr einen Fisch habt, müsst Ihr sie aufschneiden und in ihnen nach Eiern suchen.", sourceObjective = "Mak'jin möchte, dass Ihr 10 Eier von blinden Seestören im Schattenmondtal sammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[35074] = { id = 35074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzwasserpeitschflosse", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht in Talador nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Mak'jin möchte, dass Ihr 10 Eier von Schwarzwasserpeitschflossen aus Talador beschafft.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[35075] = { id = 35075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenschluckaal", description = "Wir müssen den Garnisonsteich mit einheimischen Fischen bevölkern. Könntet Ihr vielleicht bei den Spitzen von Arak nach geeigneten Fischen suchen? Wenn Ihr sie habt, müsst Ihr sie aufschneiden und nach Eiern sehen.", sourceObjective = "Mak'jin möchte, dass Ihr in den Spitzen von Arak die Eier von 10 Tiefenschluckaalen einsammelt.", progress = "Beißen sie?", completion = "Die sind genau richtig, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[35077] = { id = 35077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entpilzung", description = "Habt Ihr die Pilze draußen im Wasser gesehen? Sie wachsen schneller als ein Babyravasaurus aus Un'Goro, und wenn wir sie nicht unter Kontrolle bekommen, wird die Werkstatt genauso ruiniert wie unser letztes Dorf.\n\nOnkel Krixel hat mir immer gesagt, man soll die roten Pilze verbrennen, weil die für das schnelle Wachstum verantwortlich sind.\n\nIhr könntet uns helfen, indem Ihr einen Flammenwerfer nehmt und einige der Sporen im Watt da unten vernichtet.", sourceObjective = "Benutzt den Flammenwerfer QR58, um 20 Sporenpusteln zu zerstören.", completion = "Hey, gute Arbeit da draußen! Das hätte ich selbst nicht besser machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[35079] = { id = 35079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spor-Ex", description = "Wir haben einen Notfall!\n\nEinige Sporenbummler haben den Strand verseucht und unsere Spor-Ex-Geschütztürme zerstört.\n\nJetzt stehen wir quasi ohne Rüstung im Unterhemd da! Wenn wir diese Türme nicht wieder in Betrieb nehmen, schweben diese Sporen mitten in die Stadt hinein und dann haben wir es mit einem zweiten Quetschpfeifenkap zu tun!\n\nWir müssen da raus und sie manuell wieder einschalten.\n\nWas ist? Seid Ihr dabei?", sourceObjective = "Aktiviert 6 Spor-Ex-Geschütztürme.", completion = "Hey, Ihr habt die Spender wieder zum Laufen gebracht!\n\nGute Arbeit, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[35080] = { id = 35080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goldgrube", description = "Hey, wir haben hier eine ausgewachsene Krise! Unser Zeppelin \"Die Goldgrube\" ist über dem südlichen Gebirgszug abgestürzt.\n\nEs sollte nur ein Beobachtungsflug sein. Was sollte da schon passieren?\n\nWir müssen so schnell wie möglich dort hinunter, und dabei werde ich Eure Hilfe brauchen.\n\nKann ich auf Euch zählen?", sourceObjective = "Trefft Kimzee Quetschfpeife am Wrack der Goldgrube.", completion = "Ach du meine Güte, das ist weit schlimmer, als ich befürchtet hatte. Ich werde wirklich etwas Hilfe brauchen, um die Überlebenden da rauszuholen.\n\nGut, dass ich Euch habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35081] = { id = 35081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Helden und Kammerjägern", description = "Also, es sieht so aus.\n\nWir müssen diese Bergungsoperation so schnell wie möglich beginnen, aber das Schiff ist mitten in ein Wespennest abgestürzt.\n\nDie widerlichen Insekten sind überall, und solange die Wespen dort sind, kann ich meine Leute nicht dazu bewegen, mit ihrer Arbeit zu beginnen.\n\nGeht und tötet so viele Wespen wie möglich, dann beteilige ich Euch an der Ausbeute.", sourceObjective = "Tötet 8 Blutflügelwespen.", completion = "So macht man das! Sobald meine Mannschaft hier eintrifft, können wir mit der Arbeit beginnen.\n\nHier ist Eure Bezahlung. Danke, dass Ihr die Arbeit erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35082] = { id = 35082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenflicken der Mannschaft", description = "Meine Güte, die Trümmer sind über den ganzen Gebirgszug verteilt! Die Überlebenden werden nicht lange durchhalten, wir müssen schnell etwas unternehmen. Sie brauchen JETZT medizinische Versorgung!\n\nHier, nehmt mein Verbandszeug und flickt sie wieder zusammen.", sourceObjective = "Belebt 6 verletzte Besatzungsmitglieder wieder.", completion = "Gute Arbeit, {name}.\n\nSobald Gazwitz seine Leute hierher gebracht hat, können wir die Mannschaft wieder zur Werkstatt bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35083] = { id = 35083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterbrecht die Rituale", description = "Der Kriegshymnenklan sucht nicht länger nach der Einheit mit den Elementen. Stattdessen missbraucht er seine Macht, indem er sie einsetzt, um die Dunkelheit der Leere zu kanalisieren.\n\nIch werde nicht dulden, dass diese Rituale fortgeführt werden. Findet die Ritualtotems, die der Kriegshymnenklan zur Kanalisierung der Leere einsetzt, und zerstört sie.\n\nDas Geschenk der Elemente wurde den Orcs nicht gemacht, damit sie es schänden und damit spielen.", sourceObjective = "Zerstört die Ritualtotems.", completion = "Dunkler Schamanismus ist ein gefährlicher Zeitvertreib, {name}.\n\nEs ist wahr, dass die Leere eine Quelle furchtbarer Macht sein kann, doch diese Macht hat ihren Preis.\n\nJetzt, da Ihr diesen Ritualen einen Riegel vorgeschoben habt, sind diese Wälder wieder sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[35084] = { id = 35084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt den Ruf zum Schweigen", description = "Der Kriegshymnenklan hat sich in seinem Verlangen nach Vorherrschaft und auf der Suche nach Macht der Dunkelheit der Leere zugewandt. Dunkler Schamanismus ist eine abscheuliche, gefährliche Praxis, die das elementare Geschenk, dass ich ihm beschert habe, missbraucht.\n\nEiner des Kriegshymnenklans ruft die Leere lauter an als die anderen: ein Schamanenältester mit Namen Kuhlrath. Erschlagt ihn und den Rest seiner dunklen Schamanen.\n\nIch werde nicht zulassen, dass der Kriegshymnenklan die Elemente missbraucht und die Tradition entehrt.", sourceObjective = "Erschlagt Kuhlrath und 10 Schamanen des Kriegshymnenklans.", completion = "Das Geschenk des Schamanismus ist keines, das man leicht nehmen darf. Missbraucht ein {class} das Geschenk, erheben sich die Elemente vor Entrüstung und peinigen ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[35085] = { id = 35085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Nether", description = "Die Rituale wurden ausgesetzt, und doch leuchten die Nethersignale vor Macht...\n\nDas kann nur bedeuten, dass die Leuchtfeuer aus dem Wirbelnden Nether selbst mit Energie versorgt werden!\n\nDie Verbindung zur Leere muss durchtrennt werden! Es gibt nur einen Weg, dies zu tun: Ihr müsst die Leerenkreatur erschlagen, die die Verbindung mit unserer Welt aufrechterhält.\n\nLegt Eure Hände auf ein Signal und reist in den Wirbelnden Nether. Wenn Ihr auf der anderen Seite angekommen seid, sucht einen Schamanenstein, und verwendet ihn, um mich zu kontaktieren.", sourceObjective = "Benutzt ein Nethersignal, um in den Wirbelnden Nether zu reisen.", completion = "Der Schamanenstein scheint zu funktionieren, sogar aus dem Wirbelnden Nether heraus.\n\nEs gibt viel zu tun, {name}. Die Monster der Leere sammeln sich auf dem Oshu'gun und müssen aufgehalten werden, sonst werden sie in unser Reich einfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35086] = { id = 35086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vormarsch der Leere", description = "Versteckt hinter dem Schleier des Wirbelnden Nethers marschieren die Abscheulichkeiten der Leere gen Oshu'gun. Sie werden von der großen Leere, die tief unter dem Berg anwächst, angezogen wie Motten vom Licht.\n\nWelle um Welle marschieren die Leerenkreaturen zum Berg und opfern sich Invalidus. Der Leerenfürst Invalidus darf sich nicht an den anderen Leerenkreaturen laben, sonst wird er zu mächtig, als dass ihn noch jemand aufhalten könnte.", sourceObjective = "Vernichtet 10 Schrecken der Leere und 15 Tentakel der Leere.", completion = "Der Leerenfürst muss gestoppt werden. Dank Eurer Mühen ist der Sturm der Leerenkreaturen abgeflaut... Aber wenn wir Invalidus besiegen wollen, müssen wir schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[35087] = { id = 35087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nether rückt näher", description = "Durch die Verbindung mit dem Wirbelnden Nether hat der Kriegshymnenklan Ereignisse ausgelöst, die ungeahnte Wellen schlagen.\n\nSchaut Euch nur um, und Ihr werdet sehen, wie sich zahllose Portale öffnen. Sie sind Anzeichen dafür, dass der Wirbelnde Nether versucht, einen Pfad nach Draenor zu öffnen.\n\nSollten diese Portale erfolgreich geöffnet werden, können Dämonen und Leerenkreaturen aller Art frei dieses Tal verwüsten.", sourceObjective = "Bringt 6 Leerenportale zum Einsturz.", completion = "Wenn diese Portale sich vollends erweitern und öffnen, so würde es sämtlichen Schreckgestalten des Wirbelnden Nether den Weg nach Nagrand freigeben.\n\nDer Kriegshymnenklan hat in seinem wahnsinnigen Streben nach Macht keine Rücksicht auf Verluste genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35088] = { id = 35088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Leere", description = "Der Moment ist da, den Leerenfürst zu stellen. Invalidus wird mit jeder Minute mächtiger, daher müsst Ihr Euch beeilen, wenn Ihr das Monster besiegen wollt.\n\nAn jeder Ritualstätte des Kriegshymnenklans befindet sich ein Leerenkristall. Mit diesen Kristallen kann die Energie der Leere aus dem Wirbelnden Nether heraus kanalisiert werden.\n\nStört Ihr den Leerenkristall, wird Invalidus darunter Eure Anwesenheit spüren.\n\nSeid bereit. Sobald Ihr den Kristall gestört habt, wird Invalidus nicht lange zögern, Euch zu jagen.", sourceObjective = "Beschwört und besiegt Invalidus.", completion = "Jetzt, da Invalidus vernichtet und die Rituale des Kriegshymnenklans beendet sind, gehört die Bedrohung des Wirbelnden Nethers der Vergangenheit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[35089] = { id = 35089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volltanken, bitte", description = "Diese Flugmaschine kann uns hier rausbringen, aber ihr Treibstofftank ist knochentrocken!\n\nWir befinden uns direkt neben den Ölfeldern, aber bei den ganzen Infizierten da draußen haben wir keine Zeit, eine Leitung bis hierher zu legen, also müssen wir improvisieren.\n\nDie Ölkreaturen neben den Pumpen dort draußen sind randvoll mit einer hochwirksamen Mischung, die ich direkt in den Tank füllen könnte. Besorgt mir etwas von dem Öl, dann sind wir unserem Ziel, hier abzuhauen, einen Schritt näher.", sourceObjective = "Sammelt 4 flüchtiges Öl.", progress = "Habt Ihr mein Öl schon besorgt?", completion = "Genau, das ist es!\n\nJetzt muss ich nur noch die Zündkerzen anschließen, ein paar Löcher flicken und sie ist fast wie neu!", sourceObjectiveStatus = "unverified-source-field" }
quests[35090] = { id = 35090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Teile zur Hand", description = "Onkel Krixel ist ein zäher Knochen, aber selbst er läuft mit einem gebrochenen Bein nirgendwo zu Fuß hin.\n\nEr hat eine Flugmaschine, die er aus Azeroth mitgebracht hat. Damit könnten wir hier rausfliegen. Das Problem ist nur, dass der Motor kaputt ist.\n\nIch benötige ein paar Ersatzteile, um das Ding zu reparieren. Mein Auto ist hin, aber die kaputten Schredder draußen vor der Stadt sollten haben, was wir brauchen. Uns fehlt die Zeit, sie von Hand auseinanderzubauen, also benutzt diesen Raketenwerfer und sprengt sie in Stücke. Alles, was den Einschlag übersteht, sollte widerstandsfähig genug sein, um es in den Motor einzubauen.", sourceObjective = "Setzt die Knackerrakete G-14 ein, um brauchbare Getriebeteile aus kaputten Schreddern zu holen.", progress = "Habt Ihr irgendwelche Teile für mich?", completion = "Großartige Arbeit, {name}!\n\nGebt mir ein wenig Zeit, dann mache ich das Ding hier abflugbereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35091] = { id = 35091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporizid", description = "Es ist widerlich, vollkommen abstoßend und höchst ärgerlich!\n\nIch rede davon, dass diese Sporenkreaturen hier am Quetschpfeifenkap herumlaufen.\n\nWährend ich hier an dieser Maschine arbeite, könntet Ihr doch hinausgehen und einige dieser Sporenkreaturen töten. Ich würde mich ein wenig besser fühlen, wenn ich weiß, dass sich hier nicht mehr so viele davon herumtreiben.", sourceObjective = "Tötet 6 Sporenschlurfer am Quetschpfeifenkap.", completion = "Danke, {name}.\n\nJe weniger von diesen Sporenbiestern hier sind, desto sicherer sind wir alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[35093] = { id = 35093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Mondes", description = "Yrel und ich haben Kriegsherr Ner'zhul aufgespürt. Er trifft sich mit Grommash Höllschrei am höchsten Altar, der die Festung der Pein überblickt.\n\nTrefft Euch dort mit uns. Wir müssen ihn aufhalten.", sourceObjective = "Sucht Ner'zhul.", sourceObjectiveStatus = "unverified-source-field" }
quests[35095] = { id = 35095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlang des Flusses", description = "Durotan ist mit dem Großteil unserer Truppen gen Westen gezogen. Er errichtet einen Vorposten am Himmelsweisenfluss.\n\nEr wird sich freuen zu erfahren, dass wir bereit sind, gegen Grommashar zu ziehen.\n\nAußerdem könnte er sicher Eure Hilfe gegen die Orcs vom Kriegshymnenklan in Lok-rath gebrauchen.", sourceObjective = "Sprecht mit Durotan beim Uferposten.", completion = "Es tut gut, Euch zu sehen, Kommandant. Als wir hörten, dass die Garnisonskarawane zerstört wurde...\n\nNun ja, ich befürchtete das Schlimmste.\n\nWelche Neuigkeiten bringt Ihr aus Wor'var?", sourceObjectiveStatus = "unverified-source-field" }
quests[35096] = { id = 35096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitulationsbedingungen", description = "Ich habe gute Nachrichten, Kommandant: Wir haben Lok-rath bereits eingenommen.\n\n<Der Kriegshäuptling grinst.>\n\nDie Soldaten der Horde haben viele Krieger des Kriegshymnenklans gefangen genommen, auch ihren Anführer, Uruk Feindspalter.\n\nDie Ehre, seine Kapitulation zu akzeptieren, ist ganz die Eure. Sie warten drinnen auf Euch, Kommandant.", sourceObjective = "Sprecht mit Uruk Feindspalter in Lok-rath.", completion = "Kommandant {name}.\n\n\n\nKapitulationsbedingungen? Hmmm... lasst mich nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35097] = { id = 35097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz von Lok-rath", description = "Glaubt Ihr wirklich, der Kriegshymnenklan wäre so leicht zu besiegen?\n\n<Ein kratzendes Geräusch wie von einem Messer auf einem Seil ist zu hören.>\n\nIch bin Eure jämmerliche Horde schon jetzt leid, und dabei seid Ihr gerade erst in mein Heimatland eingefallen.\n\n<Das Geräusch wird deutlicher, während Euch Uruk Feindspalter in die Augen blickt.>\n\nEs gibt keine Kapitulation. Der Kriegshymnenklan unterwirft sich niemandem!", sourceObjective = "Tötet Uruk Feindspalter.", completion = "Schade, aber immerhin seid Ihr lebend aus der Falle entkommen und habt das Problem mit Lok-rath beseitigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35098] = { id = 35098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok-rath ist gesichert", description = "Da ihr Anführer tot ist, wird der Rest des Kriegshymnenklans eine leichte Beute sein.\n\nSobald das erledigt ist, ziehe ich unsere Soldaten aus Lok-rath ab und marschiere nach Grommashar.\n\nWenn Ihr nach Wor'var zurückkehrt, informiert Thrall, dass wir bald bereit sein werden.", sourceObjective = "Sprecht mit Thrall in Wor'var.", completion = "Wäret Ihr nicht nach Lok-rath gegangen, hätten unsere Truppen eine schreckliche Niederlage erlitten.\n\nEs tut mir leid, dass Euch eine Falle gestellt wurde. Ich vermute, Ihr habt inzwischen einen gewissen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[35099] = { id = 35099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt die Kriegsmaschinen zum Schweigen", description = "Die Eiserne Horde hat Lok-rath mit Kriegsmaschinen aus dem Eisenfausthafen versorgt. Sie werden nicht lange brauchen, um den Uferposten dem Erdboden gleichzumachen.\n\nJemand muss die Kriegsmaschinen ausschalten!", sourceObjective = "Zerstört 3 Kriegsmaschinen der Eisernen Horde.", completion = "Danke, Kommandant! Ich war sicher, wir wären erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35100] = { id = 35100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht kapitulieren will...", description = "Das ist das Rückgrat der Armee, die wir gegen Garrosh Höllschrei und Grommashar schicken wollen.\n\nWenn sie nicht kapitulieren, bleibt uns keine andere Wahl, als den Kriegshymnenklan zu eliminieren.", sourceObjective = "Tötet 10 feindliche Soldaten in Lok-rath.", completion = "Bedauerlich, doch ich habe Verständnis für den Stolz des Kriegshymnenklans. Ich würde auch niemals kapitulieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35101] = { id = 35101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken von Nagrand", description = "<Hier liegt der bleiche Körper eines gefallenen Soldaten. Blutige Spuren führen von der Leiche zu dem Höhleneingang im Norden.>\n\n<Dem Heulen und den Spuren eines Gemetzels vor der Höhle nach zu urteilen, muss sich etwas wahrhaft Furchterregendes dort drinnen aufhalten.>", sourceObjective = "Nehmt Euch Shagors Halsband von Shagor.", progress = "Kommandant. Wie kann ich Euch zu Diensten sein?", completion = "Das ist das Halsband des Tieres? Ich habe sein Heulen bis hierher gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[35102] = { id = 35102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselter Stahl", description = "Danke... <Herr/Herrin>.\n\nIch lasse Euch nicht im Stich. Ich habe nicht einmal versucht, eine der minderwertigen Klingen zu stehlen, die einer Eurer Peons direkt neben den Käfig gelegt hat. Das war übrigens eine selten dämliche Idee und irgendjemand sollte sie in Sicherheit bringen, bevor sie von jemandem mit niederen Absichten entdeckt wird.\n\nGenug geredet! Sehen wir uns mal um!", sourceObjective = "Sprecht mit Morketh Klingenschrei in Vol'jins Stolz in Talador.", completion = "Mit einfachen Waffen sind wir gut versorgt, aber ich werde sie umgehend verbessern.\n\nDanke, dass Ihr mir die Gelegenheit dazu gebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[35103] = { id = 35103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alchemistin", description = "Meine Cousine Kadar hat mir ein wenig über Alchemie beigebracht. Sie ist Alchemistin im Steinzahnposten. An sie solltet Ihr Euch wenden, falls Ihr mehr erfahren möchtet.\n\nIch hoffe bloß, dass sie den Angriff überlebt hat.", sourceObjective = "Findet Kadar in der Knochenschlucht.", completion = "Mein Lehrling... Drinnen... (Sie stirbt in Euren Armen).", sourceObjectiveStatus = "unverified-source-field" }
quests[35104] = { id = 35104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schülerin", description = "Kadars letzte Worte... Ist da noch jemand in der Hütte?", sourceObjective = "Entfernt die Trümmer und sprecht mit Ang'kra.", progress = "Sie ist bewusstlos und unter schweren umgestürzten Regalen begraben, aber sie atmet noch.", completion = "Was ist... passiert? Wo ist meine Meisterin?", sourceObjectiveStatus = "unverified-source-field" }
quests[35106] = { id = 35106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache und Rückgabe", description = "Ich werde meine Meisterin rächen und ihr Lebenswerk retten. Die Ehre verlangt es. Mein Herz will es. Und wenn es mich umbringt, der Mörder wird dafür büßen.", sourceObjective = "Tötet Kadars Mörder und holt das Buch zurück.", progress = "Ihr Mörder wird büßen!", completion = "Mein Herz zürnt, da Ihr mir mein Opfer gestohlen habt, doch mein Verstand weiß, dass ich zu schwach gewesen wäre, um meine Meisterin zu rächen. So will ich Euch vergeben, wenn Ihr mir erlaubt, meine Ehrenschuld zu begleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35128] = { id = 35128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Warnung", description = "Die Ogron hier sind nicht gerade die hellsten, aber sie sind immer noch intelligenter als die Gronn. Sie sind groß und sogar noch stärker, als sie aussehen.\n\nIhr Anführer Borogahn ist ganz besonders beeindruckend. Obwohl ich bereits einige Male gegen ihn angetreten bin, habe ich es noch nicht geschafft, ihn zu töten.\n\nHört auf meine Worte, <mein Freund/meine Liebe>. Seid vorsichtig, wenn Ihr ihr Versteck erkundet.\n\nNisha ist zum Aufbruch bereit. Bittet sie, Euch zum Eingang der Höhle zu führen. Ich bin sicher, sie wird das gern tun.", sourceObjective = "Tötet 8 Ogrongenickbrecher und Borogahn.", completion = "Die meisten Leute sind einem Ogron im Einzelkampf nicht gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35129] = { id = 35129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst jeden Soldaten zurück", description = "Hmmm.\n\nDie Ogron scheinen etwas zu haben, das für die Eiserne Horde wertvoll ist. Ich bin sicher, dass sie das nicht wissen. Wahrscheinlich haben sie nur Langeweile und wollen etwas quälen.\n\nIch neige dazu, sie sich selbst zu überlassen. Das wäre kein unverdientes Schicksal für sie. Doch wir können es uns nicht leisten, diesem Hinweis nicht nachzugehen. Mit ein wenig Glück können wir die Eiserne Horde davon abhalten, die furchtbarsten Kreaturen Gorgronds in Waffen zu verwandeln.\n\nVersucht, diesen Korporal Thukmar und seine Aufzeichnungen zu finden. Wir sehen uns dort.", sourceObjective = "Findet Korporal Thukmar und seine Geheimdokumente.", progress = "Erneut habt Ihr gute Arbeit geleistet.", completion = "Wir haben die Aufzeichnungen. Schauen wir mal, was sie über die Strategie unseres Feindes zu sagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35136] = { id = 35136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiserne Ketten", description = "Das Artefakt, das wir suchen, ist zum Greifen nah.\n\nBereitet Euch auf einen Kampf vor. Falls sie tatsächlich gelernt haben, wie man Gronn kontrolliert, könnte es heikler werden, als ich erwartet hatte.\n\nIch werde Euch in diesem Kampf beistehen, sobald Ihr angekommen seid.", sourceObjective = "Besiegt Hauptmann Brak und findet das Herz des Magnarons.", progress = "Das Artefakt gehört Euch. Ihr habt es Euch verdient.", completion = "Gute Arbeit, {name}. Dieses Artefakt können wir gegen die Eiserne Horde einsetzen, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[35137] = { id = 35137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Übungsarena", description = "Euch verdanken wir unsere Freiheit und mehr. Die anderen und ich haben einstimmig beschlossen, Euch zu Eurer Garnison zu begleiten, um den kläglichen Kreaturen, die Ihr Soldaten nennt, zu zeigen, wie man richtig kämpft.\n\nAußerdem werden wir uns bemühen, Euch unser Wissen zu vermitteln, Kommandant. Zögert nicht, uns zu rufen, wenn Ihr in der Wildnis von Gorgrond unsere Hilfe braucht.\n\nVielleicht solltet Ihr Rangari Jonaa warnen, dass wir kommen.", sourceObjective = "Sprecht mit Rangari Jonaa am Hochpass in Gorgrond.", completion = "Da wir jetzt anständige Ausbilder haben, können wir Eure Truppen dazu ausbilden, etwas anderes als Holz zu hacken. Hehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35139] = { id = 35139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge am Himmel", description = "Die Aufzeichnungen, die Ihr entdeckt habt, berichten von einem Gerät, das in der Lage ist, sogar einen Magnaron zu unterwerfen.\n\nUralte Legenden erzählen von derartigen Artefakten, die von den Weltenerschaffern gebaut wurden, um diese Kreaturen im Zaum zu halten. Ich hatte das als lächerliche Geschichten abgetan, aber wenn sie der Wahrheit entsprechen...\n\n{name}, Draenor ist dem Untergang geweiht.\n\nKeine Armee wird sie aufhalten können, wenn sie diese Macht für sich nutzen können. Wir müssen sie aufhalten oder bei dem Versuch sterben.\n\nHier, ich werde unsere Sicht an Nisha binden und hoffen, dass sie das Artefakt finden wird.", sourceObjective = "Sprecht mit Nisha.", progress = "Wir haben Glück! Das Artefakt befindet sich immer noch in Reichweite.", completion = "Gut. Nun wissen wir, wo wir das Artefakt holen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[35140] = { id = 35140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "THAELIN!", description = "Dieser kleine...!\n\n<Yrel versucht sichtlich, ihre Fassung zu bewahren.>\n\nThaelin Schwarzamboss hat uns eine Lieferung geschickt. Eigentlich sollte sie Maschinenteile enthalten.\n\nDoch als wir eine der Kisten öffneten, schlüpfte stattdessen ein Gorenbaby daraus hervor. Wisst Ihr, wie zerstörerisch die Viecher sind?\n\nUnd natürlich hat das eine Baby sofort seine Artgenossen aus den anderen Kisten befreit.\n\nWollt Ihr mir bei meiner Rache helfen?", sourceObjective = "Fangt 15 Gorenbabys.", completion = "Hervorragend!\n\n<Verteidigerin Yrel winkt Euch näher heran, damit Ihr Euch beratschlagen könnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35141] = { id = 35141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träger eingetroffen", description = "Wir werden uns bei dem kleinen Stinker revanchieren.\n\nSteckt die Gorenbabys in einen der Tragekörbe und überbringt Thaelin eine ganz besondere Lieferung.", sourceObjective = "Überbringt den Gorenbabyträger an Thaelin Schwarzamboss in der Telaaristation.\n\nBereitgestellter Gegenstand:", completion = "Haltet ein, {name}... Lasst uns nichts überstürzen! Ich höre doch, was in dem Behälter steckt.\n\nDas war nur ein harmloser Scherz.\n\nTut mir das nicht an, bitte!\n\nHalt!\n\nNicht aufmachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35142] = { id = 35142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goreninvasion!", description = "Die Erde bebt unter unseren Füßen, Kommandant. Unsere Späher sind immer noch nicht zurück. Ich spüre mit jeder Faser, dass wir bald angegriffen werden, aber aus welcher Richtung?", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Goren zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkinn, um zu beginnen.)", progress = "Wir müssen die Stellung halten!", completion = "Die Peons werden dieses Chaos beseitigen, Kommandant. Schutt und Löcher so weit das Auge blickt. Der Rest von uns wird alles nach Goren absuchen, die sich irgendwo verkrochen haben. Dann können wir uns richtig bei ihnen entschuldigen, dass wir ihren Kriegsanführer ins Jenseits befördert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35143] = { id = 35143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut der Brennenden Klinge", description = "Hallvalor ist die angestammte Heimat meines Klans, der Brennenden Klinge. Als der neue Kriegsherr und seine Familie an die Macht kamen, wurde ich verbannt, weil ich ein Halbblut bin.\n\nIch will Gerechtigkeit.\n\nIch gehe mal davon aus, dass es Euch nichts ausmacht, zu töten. Nicht dass Ihr die Wahl hättet.", sourceObjective = "Tötet 15 Truppen der Brennenden Klinge in Hallvalor.", completion = "Ein großer Sieg über die Brennende Klinge!\n\nDiese Flammenbändigerin Ka'graz scheint eindrucksvoll zu sein. Wir sollten sie und ihre Klingenmeister im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35144] = { id = 35144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Bindung", description = "Just in diesem Moment unterwerfen die Fahlen in der Schattenfallschlucht die Elemente ihrem Willen. Viele Elementargeister wurden bereits verzaubert und weitere werden folgen.\n\nDie Fahlen müssen aufgehalten und die versklavten Elementare befreit werden.\n\nBegebt Euch zur Schattenfallschlucht und befreit die Elementargeister, die noch nicht vollkommen von den Fahlen in Besitz genommen worden sind. Was die anderen betrifft, die bereits vollends zu Sklaven geworden sind: Die einzige Gnade, die wir ihnen jetzt noch gewähren können, ist das Brechen ihrer Bande durch den Tod.", sourceObjective = "Befreit 10 Elementargeister.", completion = "Cho'gall hat den Fahlen beigebracht, wie sie die Elementargeister dieses Landes versklaven können. Ein so verzauberter Elementargeist kann nicht geheilt werden, nicht einmal von einem Scharfseher wie mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[35145] = { id = 35145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fahle Bedrohung", description = "Die Fahlen sind verdorbene Wesen, die sich im Untergrund verstecken und unablässig bösartige Pläne gegen die Wesen auf der Oberfläche schmieden. Sie hausen in den Fahlen Tiefen, einer verwinkelten, dunklen Höhle unter dem Oshu'gun.\n\nUm Cho'gall aufzuhalten, müssen wir uns durch ihre Reihen bis tief unter die Erde kämpfen.\n\nBahnt Euch einen Weg in die Höhle und tötet die üblen Kreaturen und den Anführer der Fahlen, der Grauseher genannt wird.", sourceObjective = "Tötet Grauseher und 6 fahle Orcs.", completion = "Das Böse ist mir an vielerlei Orten begegnet, {name}. Sogar tief in meiner eigenen Seele sah ich dunkle Schatten dessen, was sein könnte.\n\nDas Böse in den Herzen der Fahlen jedoch trotzt jeglicher Beschreibung. Es ist auf eine Weise dunkel, abscheulich und verdorben, wie ich es noch nie zuvor erlebt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35146] = { id = 35146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gute Doktor", description = "Der Biologe unserer Expedition wurde von Schotlingen entführt!\n\nWir kamen nach Nagrand, um es zu erforschen, um die mächtigsten Bestien zu jagen und um uns an der Seite des großen Hemet Nesingwary zu beweisen.\n\nKurz nach unserer Ankunft waren Hemets Jagdkünste im Kampf gegen den Kriegshymnenklan gefragt. Wir wollten nicht tatenlos herumsitzen, also setzten wir unsere Expedition fort!\n\nAls wir gerade Zankblattdickicht erkundeten, fielen plötzlich Schotlinge über uns her! In dem folgenden Getümmel wurde Dr. Hadley Ricard entführt.\n\nBitte, rettet ihn! Wir dürfen ihn nicht einfach seinem Schicksal überlassen.", sourceObjective = "Rettet Dr. Hadley Ricard.", completion = "Ich weiß wirklich sehr zu schätzen, dass Ihr rechtzeitig angekommen seid, um mich vor den Schotlingen zu retten!\n\nDiese Forschungsstation hat schon bessere Zeiten gesehen... Meine Ausrüstung und Habseligkeiten wurden bei dem Überfall beschädigt.\n\nMit Eurer Hilfe, sind wir aber sicher in kürzester Zeit wieder einsatzbereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35147] = { id = 35147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", progress = "Was diese Oger als Müll ansehen, ist für uns bares Geld!", completion = "<Sallee Silberklammer untersucht die Fragmente, die Ihr geborgen habt.>\n\nDie sind genau richtig! Gute Arbeit, Kleiner!" }
quests[35148] = { id = 35148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger bei der Wacht", description = "Hört zu, wir haben ein paar Kundschafter ausgeschickt, um die großen stinkenden \"zivilisierten\" Oger in Mar'goks Wacht genauer unter die Lupe zu nehmen.\n\nHab schon länger nichts mehr von ihnen gehört. Genauer gesagt, nicht seit ich Euch in Telaar die Haut gerettet habe.\n\nHabt Ihr Zeit, nach ihnen zu suchen?", sourceObjective = "Findet Rangari Eleena bei Mar'goks Wacht.", completion = "Ich fürchte, es gibt Ärger.", sourceObjectiveStatus = "unverified-source-field" }
quests[35149] = { id = 35149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsarena" }
quests[35150] = { id = 35150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger bei der Wacht", description = "Gestern habe ich zwei meiner besten Kundschafter ausgeschickt, um die Oger in Mar'goks Wacht auszuspähen.\n\nBisher haben sie sich nicht zurückgemeldet.\n\n{name}, erweist Ihr mir die Ehre und sucht nach ihnen? Vermutlich ist alles in Ordnung. Die Wacht ist eine große Festung.\n\nTrotzdem würde ich mich besser fühlen, wenn ich wüsste, dass es ihnen gut geht.", sourceObjective = "Findet Akrosh bei Mar'goks Wacht.", completion = "Das Angebot Eurer Hilfe ehrt mich, Wolfsbruder. Die Lage hier ist schlimmer als wir dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35151] = { id = 35151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Garnison, Eure Entscheidung", description = "Ihr habt am Frostfeuergrat bereits eine beeindruckende Garnison errichtet. Deshalb möchte ich Euch mit einer weiteren Aufgabe betrauen.\n\nEine Region von Gorgrond ist reich an natürlichen Rohstoffen. Mit einem Sägewerk könnten wir sie optimal nutzen.\n\nEine andere Region ist die Heimat kampfgestählter Gladiatoren. Wenn wir dort eine Übungsarena errichten, könnten wir sie überzeugen, sich unserer Sache anzuschließen.\n\nDurch beide Strategien gewinnen wir an Stärke für den unausweichlichen Kampf mit der Eisernen Horde.\n\nWofür entscheidet Ihr Euch, Kommandant?", sourceObjective = "Entscheidet Euch für den Bau eines Sägewerks oder einer Übungsarena bei der Wildwacht.", completion = "Eine gute Wahl. Es wird noch viel Arbeit erfordern, bis das neue Gebäude in Eurer Garnison einsatzbereit ist, aber der Grundstein ist gelegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35152] = { id = 35152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Übungsarena", description = "Euch verdanken wir unsere Freiheit und mehr. Die anderen und ich haben einstimmig beschlossen, Euch zu Eurer Garnison zu begleiten, um den kläglichen Kreaturen, die Ihr Soldaten nennt, zu zeigen, wie man richtig kämpft.\n\nAußerdem werden wir uns bemühen, Euch unser Wissen zu vermitteln, Kommandant. Zögert nicht, uns zu rufen, wenn Ihr in der Wildnis von Gorgrond unsere Hilfe braucht.\n\nVielleicht solltet Ihr Schinder warnen, dass wir kommen.", sourceObjective = "Sprecht mit Schinder in der Wildwacht in Gorgrond.", completion = "Kash'drakor kommt hierher?! Ha! Ich sah ihn einst, wie er sich durch dutzende Lachende Schädel hindurch metzelte, weil sie seinen Sohn hatten.\n\nEr ist die pure Ausgeburt der Zerstörung.", sourceObjectiveStatus = "unverified-source-field" }
quests[35153] = { id = 35153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fungusprätorianer" }
quests[35154] = { id = 35154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz und Goren-icht gut für uns", description = "Der verlassene Minenschacht ist von Goren überrannt worden! Sie scheinen die Befehle eines großen Anführers tief unten in der Mine zu befolgen. Wenn Ihr ihn ausschalten könnt, werden sich die anderen vielleicht zurückziehen.\n\nUnd wenn Ihr erst die Goren erledigt habt, könnten wir diese Mine wieder in Gang bringen!", sourceObjective = "Tötet Steinzahn in der Garnisonsmine.", completion = "Gute Arbeit, {name}! Dann wollen wir diese Mine mal wieder in Betrieb nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35155] = { id = 35155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschen der Oger", description = "Es sind noch mehr von diesen mit Magie um sich werfenden Ogern aufgetaucht, und das ist nie ein gutes Zeichen.\n\nDiese neuen Oger sind ganz besonders herrschsüchtig und steigern die Arbeitsleistung in der Gegend gewaltig.\n\nWisst Ihr, was Oger am besten von der Arbeit abhält? Der Tod.\n\nTötet hier ein paar Oger, dann kehrt dieses Lager hoffentlich wieder zu seiner gewohnten Langeweile zurück.", sourceObjective = "Tötet 15 Oger bei Mar'goks Wacht.", completion = "Toll! Ihr habt ihnen ganz schöne Angst eingejagt. Es ist nicht leicht, zu forschen, wenn man ständig Angst haben muss, dass einem jemand mit dem Messer in den Rücken fällt!", sourceObjectiveStatus = "unverified-source-field" }
quests[35156] = { id = 35156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belastende Unterlagen", description = "Diese Kiste steckt voller Schriften und Diagramme, die verdächtig nach Forschungsmaterial zur Nullifikation von Magie aussehen. Es wäre wohl am besten, wenn Ihr jegliche dieser Bemühungen zunichtemacht, indem Ihr das Forschungsmaterial vernichtet.", sourceObjective = "Vernichtet 8 Kisten mit Forschungsmaterial der Oger bei Mar'goks Wacht.", completion = "Brennendes magisches Papier riecht ziemlich übel! Gute Idee, {name}, diese Oger dumm zu halten ist ein wasserdichter Plan!", sourceObjectiveStatus = "unverified-source-field" }
quests[35157] = { id = 35157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffsbefehle der Oger beschaffen", description = "Der obere Felsen ist von ganz besonderer Bedeutung für die Oger. Zwei imposante Ogermagier sind von dort herabgestiegen und haben angefangen, den anderen Befehle zu erteilen.\n\nGeht, holt Euch diese Befehle und trefft Euch mit meinem Späher Dalgorsh auf dem oberen Felsen. Er wird dort oben bessere Verwendung für sie haben.", sourceObjective = "Besorgt Crulgoroshs Befehle und Thulgorks Befehle bei Mar'goks Wacht.", progress = "Habt Ihr eine Ahnung, was diese Ogermagier hier wollen?", completion = "Endlich etwas Hilfe! Fast wäre ich nicht mit dem Leben davongekommen!\n\nIhr habt ein paar Ogerbefehle für mich? Mal sehen...\n\nNa, wenn das keine schlechten Nachrichten sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[35158] = { id = 35158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reglakks Forschung", description = "Nun, diesen Befehlen zufolge soll Reglakk für die Erforschung sogenannter Brecher verantwortlich sein, bei denen es sich um extrem mächtige Oger handelt. Ich weiß nicht, was Ihr davon haltet, aber für mich hört sich das alles andere als gut an.\n\nIch bin ziemlich schwer verletzt – könntet Ihr vielleicht allein dort hinaufsteigen und Reglakk bewegen, seine Forschungsabsichten noch mal zu überdenken?", sourceObjective = "Gebietet Großmagister Reglakks Forschung Einhalt.", completion = "Wir konnten ihm vorerst Einhalt gebieten, doch ich glaube, dass wir eine dauerhaftere Lösung finden sollten. Zweifelsohne ist er wieder nach Hochfels zurückgekehrt, um neue Versionen der Brecher zu ersinnen.\n\nIch halte einen Besuch der Ogerhauptstadt für längst überfällig.", sourceObjectiveStatus = "unverified-source-field" }
quests[35159] = { id = 35159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschubunterbrechung", sourceObjective = "Zerstört das Portal nach Hochfels.", completion = "Gut. Hoffentlich geben sie es bald auf, ein Portal hier einrichten zu wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35161] = { id = 35161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignetten-EP-Belohnung - Talador" }
quests[35162] = { id = 35162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Waldschreiternest" }
quests[35166] = { id = 35166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsbergung", description = "Kommandant, uns gehen allmählich die Vorräte aus.\n\nVielleicht könnten wir Material aus dem Schiff bergen, mit dem Ihr hier angekommen seid?\n\nBei dem Tempo, mit dem Leute durch das Portal kommen, wird uns bis Sonnenuntergang... oder Monduntergang alles ausgegangen sein.\n\nIch muss mich immer noch an diesen Ort gewöhnen.", sourceObjective = "Sammelt 15 Kisten mit Sklavenschiffvorräten.", progress = "Die Vorräte werden wirklich knapp, Kommandant.", completion = "Puh... Mit dem ganzen Nachschub sollten wir wieder zur Tagesordnung übergehen können.\n\nEs ist ein Segen, dass Ihr uns beschützt, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35167] = { id = 35167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen in Nagrand", description = "Hey, <mein Herr/meine Dame>, könntet Ihr mir helfen?\n\nEs gibt da ein Mädchen. Ihr Name ist Olgra. Sie ist mit ihren Eltern gestern nach Wor'var zurückgekehrt. Allerdings kamen sie niemals an und niemand will sie gesehen haben.\n\nFalls Ihr wieder aufbrecht, würdet Ihr nach ihr suchen?\n\nSie ist sozusagen meine Freundin.", sourceObjective = "Findet Mankriks Freundin Olgra.", completion = "Himmelszahn! Mama, Papa...\n\n<Das kleine Mädchen weint über den Leichnamen ihrer Familie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35168] = { id = 35168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Arbeitsauftrag für Schmiedekunst", description = "Jetzt, da Ihr über eine Schmiede verfügt, können wir Echtstahlbarren für Euch fertigen. Sprecht mit meiner Gehilfin, wenn Ihr die Bestandteile für den ersten Arbeitsauftrag zusammengetragen habt, damit wir beginnen können.", sourceObjective = "Beginnt Euren ersten Schmiedekunstarbeitsauftrag in der Schmiede und holt in anschließend ab.", progress = "Ja?", completion = "Lasst mich das für Euch auspacken.\n\nWir haben diesen Auftrag zwar schneller bearbeitet, aber Ihr solltet wissen, dass zukünftige Arbeitsaufträge zur Fertigstellung länger benötigen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35169] = { id = 35169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit für Thrall", description = "Die Zeit ist gekommen, Kommandant. Ihr habt alle Verbündeten und Stützpunkte des Kriegshymnenklans ausgeschaltet.\n\nUnsere Truppen sammeln sich vor den Toren von Grommashar. Die Rangari haben glaubwürdige Informationen, dass sich Garrosh innerhalb der Festung des Kriegshymnenklans befindet.\n\nAlle unsere Bemühungen gipfeln in diesem einen Moment. Lasst uns Garrosh ausschalten!", sourceObjective = "Sprecht mit Verteidigerin Yrel an den Toren von Grommashar und führt den Angriff auf den Kriegshymnenklan an.", completion = "Es ist vorbei. Der Kriegshymnenklan ist zerschlagen. Garrosh Höllschrei ist endlich tot.\n\nIch spüre, dass es nur eine Frage der Zeit ist, bis Grommash Rache üben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[35170] = { id = 35170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtig", description = "Sie... sie sind aus dem Nichts aufgetaucht. Aus dieser Richtung.\n\n<Das Mädchen zeigt unter Tränen ungefähr in westliche Richtung.>\n\nSie waren auf ihren bösen Wölfen.\n\nBitte, Kommandant, die Ehre meiner Familie steht auf dem Spiel. Würdet Ihr sie für mich rächen?", sourceObjective = "Tötet Worghaut den Wilden.", completion = "Habt Dank, Kommandant. Ihr seid wirklich der größte {class}, wie jeder sagt!", sourceObjectiveStatus = "unverified-source-field" }
quests[35171] = { id = 35171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit für Thrall", description = "Es wird Zeit, Kommandant. Ihr habt Euch um alle in der Nähe befindlichen Verbündeten und Besitztümer des Kriegshymnenklans gekümmert.\n\nUnsere Truppen versammeln sich vor den Toren von Grommashar. Die Schattenjäger haben zuverlässige Informationen, denen zufolge sich Garrosh in der Festung des Kriegshymnenklans verschanzt hat.\n\nAll unser Tun und Trachten hat uns diesem Moment nähergebracht. Besiegeln wir die Sache... ein für alle Mal.", sourceObjective = "Sprecht mit Durotan an den Toren von Grommashar und führt den Angriff auf den Kriegshymnenklan an.", completion = "Es ist vorbei. Der Kriegshymnenklan ist zerschlagen. Garrosh Höllschrei ist endlich tot.\n\nEs kann nur eine Frage der Zeit sein, bis Grommash Rache üben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[35172] = { id = 35172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer zweiter Arbeitsauftrag für Schmiedekunst", description = "Erteilt meiner Gehilfin einen weiteren Auftrag. Sobald er fertig ist, könnt Ihr ihn hier abholen.", sourceObjective = "Erteilt einen Arbeitsauftrag und holt ihn nach Abschluss ab.\n\nIhr könnt den Fortschritt über das Garnisonsberichtsfenster verfolgen, das über die Schaltfläche auf der Minikarte aufrufbar ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[35174] = { id = 35174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleiches Mondlicht", description = "Wir erhalten merkwürdige Berichte über einen Angriff der Orcs auf eine Draeneisiedlung in der Nähe, die Abendruhhafen heißt.\n\nWie ich höre sind diese Orcs ganz anders als alle anderen, denen wir bisher begegnet sind.\n\nSie wirken... kränklich und blass.\n\nDie Einheimischen könnten unsere Hilfe brauchen, Kommandant. Dies scheint die perfekte Gelegenheit zu sein, die Möglichkeiten unserer Garnison auszutesten.", sourceObjective = "Tötet Nag Blutsucher und 8 fahle Verschlinger.", progress = "Seht Ihr die fahlen Orcs, Kommandant?", completion = "Das ist ganz schön nervenaufreibend, muss ich sagen.\n\nDiese Dinger müssen von irgendwo unter der Erde gekommen sein.\n\nHoffentlich sehen wir die nie wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[35176] = { id = 35176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles am Laufen halten", description = "So viel Arbeit... Ich weiß überhaupt nicht, wo ich anfangen soll.\n\nDie Funktionsfähigkeit dieser Garnison sicherzustellen, ist keine einfache Aufgabe.\n\nShelly hat sich noch nicht bei mir zurückgemeldet, meine Gehilfin Funkelstein und ihre Arbeiter sind sonst wo... Ich hab so viel zu tun, dass ich noch nicht mal Zeit hatte, in unserem Garnisonslager nach Ressourcen zu schauen.\n\nWenn ich ein Magier wäre, glaubt Ihr, ich könnte einfach alles von Spiegelbildern erledigen lassen?", sourceObjective = "Sprecht mit Shelly, sucht nach Gehilfin Funkelstein und werft einen Blick in Euer Garnisonslager.", progress = "Können wir vielleicht ein andermal sprechen, Kommandant? Ich habe gerade wirklich keine Zeit zum Reden.", completion = "Was habt Ihr getan? Ihr habt mir echt das Leben gerettet, Kommandant.\n\nJetzt, da diese Aufgaben erledigt sind, sollte meine Arbeit wieder einfacher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35185] = { id = 35185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Sargerei", description = "Seid gegrüßt, {name}.\n\nErzmagier Khadgar hat eine wichtige Nachricht für Euch.\n\nDie Draenei wurden Opfer eines schändlichen Verrats, als sich Exarch Othaar, einer ihrer Anführer, als Verbündeter der Legion herausstellte.\n\nHeute nennt er sich Socrethar und wirbt in den Hügeln über dem Schattenmondtal neue Rekruten für seine Sache an.\n\nWir führen eine Geheimoperation aus, für die Erzmagierin Modera verantwortlich ist, und wir brauchen dabei Eure Unterstützung.\n\nTrefft Euch mit ihr vor Ort. Sie wird Euch alles Notwendige erklären.", sourceObjective = "Sprecht mit Seelenpriesterin Suuli auf Socrethars Klippe im Schattenmondtal.", completion = "Seid gegrüßt, {class}. Khadgar hat mir gesagt, Ihr würdet kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35186] = { id = 35186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Sargerei", description = "Seid gegrüßt, {name}.\n\nErzmagier Khadgar hat eine wichtige Nachricht für Euch.\n\nDie Draenei wurden Opfer eines schändlichen Verrats, als sich Exarch Othaar, einer ihrer Anführer, als Verbündeter der Legion herausstellte.\n\nHeute nennt er sich Socrethar und wirbt in den Hügeln über dem Schattenmondtal neue Rekruten für seine Sache an.\n\nWir führen eine Geheimoperation aus, für die Erzmagierin Modera verantwortlich ist, und wir brauchen dabei Eure Unterstützung.\n\nTrefft Euch mit ihr vor Ort. Sie wird Euch alles Notwendige erklären.", sourceObjective = "Sprecht mit Bron Himmelshorn, um ins Schattenmondtal zu kommen.", completion = "Seid gegrüßt, {class}. Khadgar hat mir gesagt, Ihr würdet kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35187] = { id = 35187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration der Sargerei", description = "Eine meiner Agentinnen hat die Ränge der Sargerei bereits infiltriert, aber Ihr müsst ihr helfen.\n\nDamit ihre Deckung aufrechterhalten werden kann, müsst Ihr Euch als einer der Feinde verkleiden.\n\nTötet Kämpfer der Sargerei, bis Ihr eine Gugel, eine Robe und ein Paar Schuhe erbeutet habt, um daraus eine Verkleidung zu erstellen.\n\nNachdem Ihr die Verkleidung angelegt habt, stellt Euch bei Seelenbinderin Zamaya als <neuer Schüler/neue Schülerin> vor und sagt dann Folgendes zu Anachoret Laanda: \"Es regnet im Schattenmondtal\".\n\nDiese Geheimphrase wird Euch als <Verbündeten/Verbündete> ausweisen.", sourceObjective = "Erbeutet eine Sargereigugel, eine Sargereirobe und Sargereischuhe, um eine Sargereiverkleidung zu erstellen. Legt die Verkleidung an und sprecht dann mit Seelenbinderin Zamaya und Anachoret Laanda.", progress = "Ja, Initiand?", completion = "Willkommen. Mit der Zeit habe ich mir bei den Sargerei einen recht guten Namen gemacht, aber ihre Geheimnisse hüten sie wie ihre eigenen Augäpfel.\n\nDie Sargerei akzeptieren nur die Stärksten der Starken in ihren Reihen.\n\nSeelenpriesterin Zamaya hat hier bei uns das Sagen. Wenn Ihr uns helfen wollt, müsst Ihr zunächst ihr Vertrauen gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35188] = { id = 35188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lästige Schotlinge", description = "Ah, <Initiand/Initiandin>. Seid Ihr für Eure erste Aufgabe bereit?\n\nDie Wälder im Süden sind voller lästiger Schotlinge. Die widerlichen Dinger graben unsere Farmen um, stehlen Vorräte und vergreifen sich an nichtsahnenden Auszubildenden.\n\nSie sind eklige, schreckliche Kreaturen, die ausgelöscht werden müssen.\n\n<Zamaya schaut Euch zweifelnd an.>\n\nIch benötige ihre Speere als Beweis dafür, dass Ihr die Aufgabe erledigt habt.", sourceObjective = "Sammelt 8 hölzerne Speere.\n\nFalls Ihr Eure Verkleidung verliert, tötet Kämpfer der Sargerei und erbeutet so eine Sargereigugel, eine Sargereirobe und Sargereischuhe, um eine Sargereiverkleidung zu erstellen.", progress = "Diese widerlichen Kreaturen verdienen es nicht, zu leben.", completion = "Von einem Initianden würde ich auch nicht weniger erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35189] = { id = 35189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wort des Socrethar", description = "Die Sargerei folgen Socrethar mit fanatischem Eifer. Nach allem, was ich in Erfahrung bringen konnte, ist er ein ausgesprochen charismatischer und inspirierender Anführer.\n\nViele der Initianden tragen Bücher mit seinen Schriften bei sich.\n\nIhr müsst diese Werke lesen und mir dann Bericht erstatten. Wenn wir erst einmal verstehen, was die Sargerei antreibt, können wir sie vielleicht unterwandern.\n\nZuletzt habe ich diese Bücher in der Nähe des Sees gesehen, auf einem Tisch bei dem Brunnen und im Haus bei den Gärten.", sourceObjective = "Lest \"Das Schicksal der Eredar\", \"Der Zweck der Eintracht\" und \"Ein Versprechen der Unvergänglichkeit\".", completion = "Ich verstehe... Socrethar hat völlig den Verstand verloren, aber seine Argumente sind logisch. Kein Wunder, dass sich so viele Draenei seiner Sache anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35190] = { id = 35190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine urtümliche Bedrohung", description = "Im Nordwesten hat sich ein uraltes Wesen auf einer Waldlichtung niedergelassen.\n\nIch brauche jemanden, der diese lästige Störung beseitigt.\n\nDiese einfache Aufgabe sollte selbst für <einen Initianden/eine Initiandin> wie Euch kein Problem darstellen.", sourceObjective = "Tötet Ahnenmoos.\n\nFalls Ihr Eure Verkleidung verliert, tötet Kämpfer der Sargerei und erbeutet so eine Sargereigugel, eine Sargereirobe und Sargereischuhe, um eine Sargereiverkleidung zu erstellen.", completion = "Gar nicht so übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[35191] = { id = 35191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zerschmetterte Feind", description = "Während Ihr vorgebt, Zamayas Befehle auszuführen, können wir die Sargerei direkt vor ihrer eigenen Nase sabotieren.\n\nÜberall in diesem Dorf finden sich Teufelssturmkristalle. Damit verstärkt der Feind seine Macht.\n\nZerstört diese Kristalle, dann werden ihre Pläne mächtig ins Stocken geraten.", sourceObjective = "Zerstört 6 Teufelssturmkristalle.", completion = "Sehr gut. Unsere Mission geht unbemerkt weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[35192] = { id = 35192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkungsteleportation beobachten" }
quests[35194] = { id = 35194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen entgegentreten", description = "Die Zeit wird knapp, {name}. Die Sargerei haben auf dem Hügel im Westen ein Beschwörungsportal geöffnet.\n\nIch glaube, sie wollen mit diesem Portal eine Armee von Dämonen hier in das Schattenmondtal bringen.\n\nWir müssen das um jeden Preis verhindern. Nehmt diese arkane Bombe und zerstört damit das Portal.\n\nDann fliegt vielleicht auch unsere Tarnung auf, aber das Portal zu zerstören, hat jetzt Vorrang.", sourceObjective = "Besiegt Invokaz und zerstört das Dämonentor.", completion = "<Seltsamerweise ist Anachoret Laanda verschwunden. Was ist hier geschehen?>", sourceObjectiveStatus = "unverified-source-field" }
quests[35195] = { id = 35195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethars Zorn", description = "<Ihr öffnet die Schriftrolle und findet darin eine Nachricht von Anachoret Laanda.>\n\nIch bin in großer Eile, während ich diese Zeilen schreibe. Man hat mich entdeckt, und ich werde nun Socrethar vorgeführt.\n\nIhr müsst unsere Mission fortsetzen. Ich habe erfahren, dass Seelenbinderin Zamaya einen detaillierten Plan zu Socrethars nächstem Angriff besitzt.\n\nSie vertraut Euch nach wie vor, Ihr solltet also problemlos in das Hauptgebäude gelangen. Ihr müsst diese Pläne finden, {name}!", sourceObjective = "Stellt Socrethar, und beschafft dann die Schlachtpläne der Sargerei von Seelenbinderin Zamaya.", progress = "Macht Euch um mich keine Sorgen.", completion = "<Anachoret Laanda sieht bleich aus. Er wird es nicht schaffen.>\n\n{name}... Ich danke Euch für alles, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35196] = { id = 35196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft schmieden", description = "<Die Stimme von Anachoret Laanda ist nur noch ein Hauch.>\n\nIhr müsst Euch bei... Khadgar zurückmelden.\n\nSocrethar will Shattrath einnehmen. Er wird... weitere Anhänger... an seine Seite rekrutieren...\n\nDanke, dass Ihr... mir in meiner letzten Stunde helft...\n\nVerlasst mich nun... Ich möchte ruhen...", sourceObjective = "Kehrt zu Khadgars Diener in Eurer Garnison zurück.", completion = "Offensichtlich hat es Socrethar zunächst auf Shattrath und Auchindoun abgesehen. Aber damit wird er sich nicht zufrieden geben.\n\nDanke für diese Informationen, {name}.\n\nIch werde sie sofort an Erzmagier Khadgar weiterleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35197] = { id = 35197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft schmieden", description = "<Die Stimme von Anachoret Laanda ist nur noch ein Hauch.>\n\nIhr müsst Euch bei... Khadgar zurückmelden.\n\nSocrethar will Shattrath einnehmen. Er wird... weitere Anhänger... an seine Seite rekrutieren...\n\nDanke, dass Ihr... mir in meiner letzten Stunde helft...\n\nVerlasst mich nun... Ich möchte ruhen...", sourceObjective = "Kehrt zu Khadgars Diener in Eurer Garnison im Frostfeuergrat zurück.", completion = "Offensichtlich hat es Socrethar zunächst auf Shattrath und Auchindoun abgesehen. Aber damit wird er sich nicht zufrieden geben.\n\nDanke für diese Informationen, {name}.\n\nIch werde sie sofort an Erzmagier Khadgar weiterleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35201] = { id = 35201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krixel" }
quests[35202] = { id = 35202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüllen für Xais", description = "Die Magie, die Xais beherrscht, lässt Euch große Taten vollbringen, aber es müssen Vorbereitungen getroffen werden, bevor die Geister uns mit ihrer Macht segnen werden.\n\nXais braucht viele Hüllen dieser lästigen Goren. Um sie zu sammeln, wird Xais ein Geheimnis preisgeben.\n\nNähert Euch ihren Tunnelausgängen, und die Goren springen heraus. Auf die Art könnt Ihr viele gleichzeitig töten.", sourceObjective = "Sammelt 9 Gorenpanzer von Friedhofschlingern.", progress = "Toller Xais!", completion = "Ahh, ja. Xais ist wieder einen Schritt weiter, ein Wunder zu vollbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35204] = { id = 35204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollenpotenzial!", description = "Die Botani setzen monströse insektenartige Kreaturen ein, um ihre Blüten zu bestäuben.\n\nIhre Pollen verfügen über einige mächtige Eigenschaften, die Euren Garnisonstruppen wirklich helfen könnten.\n\nWenn Ihr mir einen Vorrat der Pollen bringt, kann ich daraus bestimmt etwas Wertvolles machen.", sourceObjective = "Sammelt 20 starke Pollen.", progress = "Habt Ihr die Pollen?", completion = "Macht weiter so, dann werdet Ihr noch zum Überlebenskünstler.", sourceObjectiveStatus = "unverified-source-field" }
quests[35205] = { id = 35205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrennt die Leichen", description = "Ihr scheint nicht zu begreifen. Alles, was diese Pflanzendinger nicht befallen, mästen sie, um Dünger daraus zu machen.\n\nIch schlage vor, wir kümmern uns um ihre Nahrungsquelle.\n\nIch habe gesehen, dass die Botani einige Leichen herumliegen hatten. Vielleicht wäre es eine gute Idee, sie zu verbrennen.\n\nWollen wir doch mal sehen, ob sie auch Asche befallen können.", sourceObjective = "Verbrennt 6 verkompostierende Leichen.", completion = "Eigentlich gehöre ich nicht zu der gewalttätigen Sorte von Zwergen, aber ich werde hier nicht tatenlos rumsitzen und darauf warten, bis ich in ein Gebüsch verwandelt werde. Und ich werde nicht zulassen, dass es mit anderen passiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[35206] = { id = 35206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buschräuber", description = "Wir suchen weiterhin nach Thaelins Leuten, aber diese Botani sind eine größere Bedrohung als wir dachten.\n\nIhre Opfer zu befallen... das ist einfach nur bestialisch.\n\nBitte Kommandant, wenn Ihr zu den Immermornquellen westlich von uns gelangt, tötet so viele dieser Viecher, wie Ihr könnt.\n\nGebietet diesem grausamen Treiben Einhalt und führt diese Biester ihrer gerechten Strafe zu.", sourceObjective = "Tötet 7 Blütenweber.", completion = "Gute Arbeit, Kommandant. In jeder Situation beweist Ihr ein Kriegsgeschick, das selbst unsere erfahrensten Exarchen herausfordern würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[35207] = { id = 35207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kohlenstaubs Rache", description = "Ich bin so satt, ich könnte keine Axt mehr schwingen, selbst wenn ich eine hätte.\n\nIch sag Euch was: Für uns beide gibt es hier eine tolle Gelegenheit. Ihr helft mir, mich ein wenig an den großen Botani im hinteren Gebiet des Flors zu rächen, und ich zeige Euch, wo die Botani eine geheime Waffe versteckt haben.", sourceObjective = "Tötet 3 Taumeister.", completion = "Meine Mutter hat ja immer gesagt, ich soll mein Gemüse essen. Aber das hier schwebte ihr bestimmt nicht vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[35208] = { id = 35208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenabschuss", description = "In Eurer Abwesenheit haben unsere Rangari hier noch mehr Hinweise auf ein paar andere meiner Freunde gefunden.\n\nBurrian Kohlenstaub und Sengbraue.\n\nNur leider führt ihre Spur direkt zu den Immermornquellen im Westen.\n\nBitte, Kommandant, könnt Ihr sie vor dem Vermulchen retten?", sourceObjective = "Findet Burrian Kohlenstaub bei den Immermornquellen.", completion = "Oh! Es war schrecklich! Sie haben mich gezwungen, all diese Nahrung in mich reinzustopfen.\n\nVersteht mich nicht falsch, ich liebe eine gute Mahlzeit, aber diese Pflanzendinger haben mir den ganzen Tag nur Früchte vorgesetzt.\n\nIch kann nich' mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[35209] = { id = 35209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle des Lebens", description = "Wir kamen also her, weil wir eine Waffe brauchten, die wir bei den Botani gesehen haben.\n\nHansel schnappte sich das Artefakt, und Sengbraue und ich sollten uns das besondere Wasser schnappen, mit dem das Ding läuft.\n\nNur wussten wir nicht, dass sich aus Wasser, das so voller Leben steckt, ein Elementar bilden kann.\n\nWenn Ihr zu dem Kessel unten an dem schicken alten Artefakt in den Immermornquellen schleicht, findet ihr das Biest. Wenn Ihr es erledigt und sein Wasser beschafft, können wir es benutzen, sobald wir den Rest des Artefaktes haben.", sourceObjective = "Schöpft Wasser von Utrophis.", progress = "Jetzt weiß ich, warum manche Rangari werden. Ist das spannend!", completion = "Ihr tragt etwas von großer Macht bei Euch. Das konnte ich spüren, als Ihr näher kamt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35210] = { id = 35210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Flucht", description = "Ein Gorentunnel!\n\nSobald der Weg freigeräumt ist, sollte er aus dieser vom Licht verlassenen Grube nach draußen führen.", sourceObjective = "Macht den Gorentunnel frei und benutzt ihn, um Euch mit Rexxar vor dem Spalt der Wut zu treffen.", completion = "Diese Gorentunnel haben sich als sehr nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35211] = { id = 35211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schlimmste verhindern", description = "Habt Ihr den Pilzbefall auf den Gebäuden am Quetschpfeifenkap gesehen? Es dauert nicht mehr lange, dann werden genug Sporen freigesetzt, um die ganze Küstenlinie zu verseuchen!\n\nBei den Befallenen, die sich immer noch am Quetschpfeifenkap befinden, ist die Infektion bereits zu weit fortgeschritten, und wir können sie nicht mehr retten. Also tun wir das Richtige und erlösen sie von ihrem Leid, um einen noch größeren Ausbruch zu verhindern.\n\nIch habe einige Feuerbomben gebaut, die den Pilzbefall niederbrennen werden, aber Ihr müsst sie für mich platzieren, während ich den Zünder vorbereite.\n\nSeid Ihr dazu bereit?", sourceObjective = "Platziert 5 Feuerbomben am Quetschpfeifenkap.", completion = "Gute Arbeit!\n\nSo, ich muss nur den Zündmechanismus fertig vorbereiten, dann sind wir so weit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35212] = { id = 35212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefwurzel", description = "Da Ihr ja jetzt bereit seid, Euch mit Bäumen und Büschen anzulegen, könnt Ihr mir einen Gefallen tun.\n\nIch kam nach Gorgrond, weil ich nach einer Expedition meiner Dunkeleisenkumpel suche, die hierher unterwegs war. Leider habe ich ihre Spur verloren.\n\nIch mache mich jetzt nach Süden auf, um nach ihnen zu suchen. Aber im Süden wimmelt es nur so von Botani, Schotlingen, Riesenbäumen und anderem übellaunigen Pflanzenzeugs.\n\nDie Vorräte Eures Holzfällerlagers wären wirklich eine große Hilfe. Wenn Ihr mir bei der Suche nach meinen Freunden helft, dann schwöre ich, werden wir Euch nach besten Kräften unterstützen.", sourceObjective = "Trefft Euch mit Thaelin Schwarzamboss in Tiefwurzel.", completion = "Ah, gut! Ihr habt's geschafft.\n\nDie Mädels hier wollten unbedingt mitkommen, auch wenn sie einander offenbar nicht besonders mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35213] = { id = 35213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klingenflor", description = "Kaalya glaubt, sie hätte eine Spur gefunden. Anscheinend ist eine Gruppe Zwerge nach Norden in den Klingenflor gegangen.\n\nAber da wimmelt es nur so von Pflanzenleuten. Und gegen Pflanzenleute kann ich nicht viel ausrichten.\n\nWürdet Ihr der Sache mal nachgehen?", sourceObjective = "Sucht Hinweise auf den Verbleib von Lera Aschzeh, Nori Rußbart und Rauschebart.", completion = "Das Pflanzenvolk hat meine Freunde mit jeder Menge Früchte und Honig und Met versorgt. Ich glaube, die wollten sie mästen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35214] = { id = 35214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befallenen", description = "D'kaan hat zwar nichts gesagt, aber die Botani haben noch mehr Rangari erwischt als die, die Ihr gefunden habt.\n\nEr glaubt, sie wurden ermordet, aber ich befürchte, dass es noch viel schlimmer ist.\n\nVielleicht wagt Ihr Euch ja in den Klingenflor. Wenn ja, dann findet Ihr vielleicht heraus, was die Botani mit ihren... \"Gefangenen\" anstellen.\n\nBitte erlöst diese armen Seelen von ihrem Schicksal.", sourceObjective = "Tötet 6 Befallene.", completion = "Ich danke Euch, dass Ihr das getan habt, was ich nicht über mich brachte.\n\nEs ist das einzig Richtige, aber es ist schwer, den Pfeil fliegen zu lassen, wenn das Ziel einst ein guter Freund war.", sourceObjectiveStatus = "unverified-source-field" }
quests[35215] = { id = 35215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Iyus", description = "Tagebucheintrag 25 -\n\nDie Botani haben jetzt einen Anführer. Er... ähm... Sie... ähm... Es nennt sich die Stimme von Iyu.\n\nAnscheinend betrachten die Botani die Genesaurier als Götter, und nur die herrischsten der Botani dürfen im Namen der Genesaurier sprechen.\n\nAls wir nach dem Artefakt fragten, das wir auf der Basis gefunden hatten, wurde es ganz wütend und hat Lera und Nori weggeschickt. Seither habe ich keinen von beiden mehr gesehen.\n\nMir ist bei der ganzen Sache gar nicht wohl.", sourceObjective = "Tötet die Stimme Iyus.", completion = "Sie haben meine Freunde zu Mulch verarbeitet? Diese Spitzastwedler mit ihren kleinen glänzenden Augen! Danke, dass Ihr meine Freunde gerächt habt.\n\nWir suchen besser die anderen, bevor sie noch zu Pflanzenfutter verarbeitet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35216] = { id = 35216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supersamen", description = "Diese Samen wurden sorgfältig von den Botani geschützt.\n\nDie winzigen Gefäße des Lebens scheinen mit gewaltiger Energie erfüllt.\n\nDies könnte sich noch als nützlich erweisen.", sourceObjective = "Sammelt angereicherte Samen.", progress = "Und, was habt Ihr gefunden?", completion = "Ich versteh vielleicht nich' viel von Landwirtschaft, aber ich erkenne eine Energiequelle, wenn ich sie vor mir seh'. Diese Samen haben ordentlich Saft.\n\nGut geschaltet von Euch, dass Ihr sie gleich eingesackt habt, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35218] = { id = 35218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Eisernen Horde", description = "Geisterschwinge hat an den Felsen in der Nähe des Lagers der Eisernen Horde Befehle entdeckt. Sie müssen Euch entgangen sein, als Ihr dort wart. Könntet Ihr nachsehen, ob Ihr sie nun findet?", sourceObjective = "Sucht nach Gronnkontrollbefehlen im Lager der Eisernen Horde in Malmzahns Ende.", completion = "Diese Befehle sind in einer miserablen Handschrift verfasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[35219] = { id = 35219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Die Brennende Front" }
quests[35220] = { id = 35220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Kharazos der Triumphale" }
quests[35221] = { id = 35221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hüter" }
quests[35225] = { id = 35225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schwere helfende Hand", description = "Burrian hat uns die Koordinaten der Dunkeleisenbasis gegeben. Sie haben sie Moiras Vorstoß getauft.\n\nDoch als sie gerade mitten im Bau war, wurde die Basis von Goren befallen.\n\nWenn Ihr nach Süden aufbrecht, solltet Ihr auf sie stoßen. Haltet einfach Ausschau nach 'ner großen Kanone.\n\nWir stoßen zu Euch, sobald wir diesen verflixten Panzer hier losgeeist haben.", sourceObjective = "Findet Überlebende der Dunkeleisenzwerge.", completion = "Ko... Kommandant? Was für ein erfreulicher Anblick!\n\nIch hätte nicht gedacht, dass ein Freund nach mir suchen würde.\n\nWir haben ein Artefakt gefunden, das ziemlich nützlich gegen das Völkchen in diesem Gebiet zu sein schien, doch dann sind diese säurespeienden Asseln aufgetaucht und haben angefangen, alles aufzufressen.\n\nHelft mir hoch, dann können wir wieder loslegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35226] = { id = 35226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Freunde, neue Feinde", description = "Ich kann nach all dieser Zerstörung nicht glauben, dass Orgrim weiterhin Schwarzfaust unterstützt.\n\nWir müssen ihn aufsuchen. Trefft mich im Dorf an der Orunaiküste. Dann werden wir die Sache mit meinem ältesten Freund klären.", sourceObjective = "Sucht Orgrim Schicksalshammer im Dorf an der Orunaiküste auf.", completion = "Ogrim will nicht zur Vernunft kommen. Also müssen wir ihn aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35227] = { id = 35227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiplomatie", description = "Oger sind Oger. Sie mögen vielleicht Geister sein, aber die Ango'rosh bilden da keine Ausnahme.\n\nTrotz ihrer Ritualbücher werden sie Euch keine Macht überlassen, bis Ihr Euch als würdig erwiesen habt.\n\nIch habe mein ganzes Leben lang gegen Oger gekämpft. Ich weiß, dass es nur eine Möglichkeit gibt, das zu erreichen.\n\nIhr müsst sie töten.\n\nJe mehr Geister der Ango'rosh und ihrer Haustiere Ihr dort töten könnt, desto mehr Respekt werdet Ihr ihnen abnötigen.", sourceObjective = "Tötet 10 Ango'rosh in den Ruinen der Ango'rosh.", completion = "Wieder mal erfolgreiche Verhandlungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35229] = { id = 35229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter in den Gorenbau", description = "Diese Biester haben uns so schnell überrannt, dass wir keine vernünftige Verteidigung aufbauen konnten. Sie haben sich direkt über das Metall hergemacht und sich durch alle Wände gefressen.\n\nWenn wir nicht bald ein paar von ihnen töten, werden sie die ganze Festung zerstören.", sourceObjective = "Tötet 5 Goren in Moiras Vorstoß.", completion = "Schwarzfelsorcs, Troggs und Lepragnome: Alles kein Problem. Aber diese verfressenen Säurebestien machen uns fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[35231] = { id = 35231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterangelegenheiten", description = "Die Geister der Toten zieht es schon seit Langem nach Oshu'gun.\n\nSo lange ich mich erinnern kann, führt die gespenstische Pilgerfahrt die Geister der Urahnen auf ihrem Weg in das Innere des Berges durch den Wald.\n\nIch fürchte, hierbei handelt es sich nicht um eine normale Geistwanderung, wie ich sie schon vorher beobachtet habe.\n\nBegebt Euch zum Ahnengrund und nehmt Kontakt zu den Geistern auf. Findet heraus, was dort vor sich geht.", sourceObjective = "Sprecht mit den Geistern beim Ahnengrund.", completion = "Die Situation hier ist ernst, {name}, aber ich hatte so ein Gefühl, dass wir uns wiedersehen.\n\nIch höre den Ruf der Leere nicht so laut wie die anderen, da ich noch nicht so lange tot bin und mein Leichnam weit von hier entfernt liegt.\n\nDas wird sich jedoch mit der Zeit ändern.\n\nWenn Ihr hier seid, um zu helfen, dann hört gut zu, denn die Zeit wird knapp.", sourceObjectiveStatus = "unverified-source-field" }
quests[35232] = { id = 35232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Oshu'gun", description = "Die Elemente haben gesprochen und uns eine Vision zukommen lassen, {name}.\n\nWir werden zusammen zum großen Berg Oshu'gun reisen und dem finsteren Einfluss dort ein Ende machen.\n\nWenn die Bilder Eurer Vision nicht trügen, erwarten uns große Gefahren.\n\nWir treffen uns im Geisterwald am Fuße des Oshu'gun. Wenn Ihr bereit seid aufzubrechen, dann sprecht mit Gixmo Goldscheffel. Er wird Euch dann hinfliegen.", sourceObjective = "Fliegt zum Geisterwald.", completion = "Es ist schon so viele Jahre her, seit ich zuletzt in diesem Wald war.\n\nBeim letzten Mal war ich anlässlich des Kosh'harg hier, als sich alle Klans hier zusammenfanden. Aber das ist lange her und jetzt weht hier nur noch das Banner des Kriegshymnenklans.", sourceObjectiveStatus = "unverified-source-field" }
quests[35233] = { id = 35233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Fall der Fälle", description = "Als wir hier unser Lager aufschlugen, war die Kanone das Erste, was wir gebaut haben. Schien der richtige Ort dafür zu sein.\n\nWir haben gerade die Basis um sie herum gebaut, als diese Säure sabbernden Viecher plötzlich aus dem Boden gekrabbelt kamen.\n\nAber immerhin ist die Kanone fertig. Es fehlt nur Munition.\n\nWir müssen dort sowieso ganz runter, also könntet Ihr auch gleich einige Verdammnisgeschosse mitnehmen, wenn Ihr welche findet.\n\nEs ist besser, die Kanone zu laden und nicht zu brauchen, als sie zu brauchen und nicht geladen zu haben.", sourceObjective = "Sammelt Verdammnisgeschosse.", progress = "Habt Ihr die Munition?", completion = "Ich hoffe ja, dass wir die große Kanone nicht abfeuern müssen, aber eigentlich kann ich es kaum erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35234] = { id = 35234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wille der Genesaurier", description = "Als die Goren einfielen, schleuderten wir ihnen alles entgegen, was wir hatten, aber es kamen immer mehr.\n\nEin paar der Jungs sind dann losgezogen und haben so ein schickes Artefakt von den Botani geklaut.\n\nDas Problem war nur, dass wir nicht wussten, wie man es verwendet. Jetzt versauert das Artefakt im tiefsten Keller der Bastion. Um dort hinzugelangen, müsst Ihr an all den Goren vorbei nach ganz hinten in den Tunneln gehen und den winzigen Abzweig finden, der Euch noch weiter in den Untergrund führt.\n\nWenn Ihr es findet, dürft Ihr es behalten.", sourceObjective = "Bergt den Willen der Genesaurier.", progress = "Es gefällt mir hier nicht. Wenn einen die Pflanzen nicht gerade umbringen wollen, versucht der Boden, einen zu verschlucken.", completion = "Das Artefakt war nützlich, bis uns der Saft dafür ausging. Hoffentlich findet Ihr ein paar Samen und das nötige Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[35235] = { id = 35235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iyu", description = "Habt Ihr das gehört?\n\nScheint ganz so, als hätte dieser Genesaurier gerne seinen \"Willen\" wieder. Ich sag Euch ja, dieser Ort bringt nix als Unglück.\n\nIch werde die Munition, die Ihr mir gebracht habt, anständig laden und schauen, ob wir das Ding weichklopf'n können. Aber Ihr macht Euch lieber nach da oben auf und kümmert Euch um unseren Besuch...", sourceObjective = "Besiegt Iyu.", completion = "Das hatte es in sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[35236] = { id = 35236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orunaiküste" }
quests[35237] = { id = 35237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rodung von Mor'gran" }
quests[35238] = { id = 35238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Besitzer", sourceObjective = "Kampfbot 8000, Eigentümer erfasst: {name}.\n\nAktueller Wunsch: Feinde von {name} massieren... bis zum Tod.", sourceObjectiveStatus = "unverified-source-field" }
quests[35239] = { id = 35239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Besitzer", sourceObjective = "Kampfbot 8000, Eigentümer erfasst: {name}.\n\nAktueller Befehl: Feinde von {name} massieren... bis zum Tod.", sourceObjectiveStatus = "unverified-source-field" }
quests[35240] = { id = 35240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeblutet", description = "<Der Draenei stößt seine letzten Worte hervor.>\n\nSie hielten uns in Käfigen gefangen. Sie... haben uns das Blut entzogen... für Rituale...\n\n<Er hustet stark.>\n\n...noch viele...\n\n... mein Volk...\n\n<Der Draenei stirbt.>", sourceObjective = "Befreit die Sklaven aus den 2 Käfigen des Blutenden Auges in Herzblut.", completion = "Gut gemacht, {name}.\n\nSie sind vielleicht verletzt, halb verhungert und schlecht ausgerüstet... aber keine Klinge ist so scharf wie ein rachedurstiger Geist, keine Rüstung so dick wie ein rechtschaffenes Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[35241] = { id = 35241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Gefallenen", description = "Der Klan des Blutenden Auges hat schon zu viele meiner Leute ermordet. Ihre Grausamkeiten müssen gerächt werden.\n\n<Der trauernde Orc sieht Euch an.>\n\nLasst sie dafür bezahlen.", sourceObjective = "Tötet 6 Orcs des Blutenden Auges.", completion = "Ich bewundere Euer Pflichtbewusstsein, {name}. Auch wenn Euer eigenes Überleben in der Schwebe hängt, findet Ihr immer noch Zeit, einer trauernden Witwe Seelenruhe zu bringen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35242] = { id = 35242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Gefallenen", description = "Der Klan des Blutenden Auges hat schon zu viele meiner Leute ermordet. Ihre Grausamkeiten müssen gerächt werden.\n\n<Die trauernde Draenei schaut Euch an.>\n\nLasst sie dafür bezahlen.", sourceObjective = "Tötet 6 Orcs des Blutenden Auges.", completion = "Ich bewundere Euren Gerechtigkeitssinn, {name}. Auch wenn Euer eigenes Überleben in der Schwebe hängt, findet Ihr immer noch Zeit, Rache für eine trauernde Witwe zu nehmen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35243] = { id = 35243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk der Dunklen Fürstin", sourceObjective = "Man hat mir aufgetragen, Euch zu finden und in Eure Dienste zu treten. Was immer Ihr von mir haben wollt, Ihr sollt es bekommen. Es bereitet mir eine besondere Freude, Dinge zu Asche zu verbrennen.\n\nDie dunkle Fürstin entbietet ihre Grüße.", sourceObjectiveStatus = "unverified-source-field" }
quests[35244] = { id = 35244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skagg" }
quests[35245] = { id = 35245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sentimentales Relikt", description = "Der Armreif meines Vaters war jahrelang hier, bevor ihn dieser Betrüger Ikiss gestohlen hat.\n\nIch danke Euch dafür, dass Ihr ihn mir zurückgebracht habt, aber ich habe keine Verwendung für Andenken. Behaltet ihn, Ihr habt meinen Segen.\n\nFalls es immer noch Krallenpriester gibt, die dem wahren Klauenkönig treu ergeben sind, bringt ihn bitte zu ihnen.", sourceObjective = "Bringt Lithics Geschenk zu Reshad im Terokkversteck.", progress = "Hm? Was habt Ihr da?", completion = "Lithic hat tatsächlich mit Euch gesprochen? Oder zumindest... eine Art Schatten von ihr...\n\nFaszinierend!", sourceObjectiveStatus = "unverified-source-field" }
quests[35247] = { id = 35247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist Xais egal", description = "Die Geister haben mit mir gesprochen. Sie glauben, dass der Magnaron Gro der Zerschöpfer sich unserem Kampf anschließen und seine Untergebenen gegen die Eiserne Horde führen wird.\n\nEine derartige Ehre wurde noch keinem Lachenden Schädel zuteil, wenigstens nicht zu meinen Lebzeiten.\n\nIch werde mit dem Magnaron kommunizieren, und gemeinsam werden wir die Eiserne Horde vernichten.", sourceObjective = "Sprecht mit dem Knochigen Xais und beobachtet ihn bei seiner Kontaktaufnahme zu Gro dem Zerschöpfer.", completion = "Die Geister meiner Ahnen haben mich verraten! Ihre Schädel lachen mich sicherlich aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[35248] = { id = 35248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhilfe in Sachen Wildheit", description = "Willkommen an der Front, <Fremder/Fremde>, hier, wo Ödland und Dschungel aufeinandertreffen. \n\nWenn Truppen des Lachenden Schädels die Wildheit ihres Klans vergessen, bekommen sie hier etwas Nachhilfe.\n\nKompromisslose und unbarmherzige Zerstörung sichert unser Überleben. So läuft es in Gorgrond.\n\nMacht es uns nach! Zeigt uns, ob Ihr der Brutalität unseres Landes standhaltet.", sourceObjective = "Tötet 8 Bewohner der Einöde am Leidensgrat.", completion = "Ich mag Töten. Und Knochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35249] = { id = 35249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie für die Verteidigung", description = "Gut, dass ein Champion der Horde sich dem Kampf anschließt.\n\nDie Verteidigung von Auchindoun wird nicht mehr lange halten. Ein paar der Auchenaiseelenpriester, die nicht an der Front sind, arbeiten fieberhaft daran, sie aufrecht zu erhalten.\n\nSeelenbinderin Tuulani ist in das nahe gelegene Grab des Lichts gegangen, um einen Reserveenergiepylon zu holen. Aber sie ist noch nicht wieder zurückgekehrt. Es wäre eine riesige Hilfe, wenn Ihr sie finden und zusammen mit dem Pylon sicher hierher zurückeskortieren könntet.", sourceObjective = "Findet Seelenbinderin Tuulani im Grab des Lichts.", completion = "Ihr seht aus, als würdet Ihr verstehen zu kämpfen! Wir müssen von hier verschwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[35251] = { id = 35251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute der Speerspießerfestung", description = "An der triumphalen Eroberung der Festung habt Ihr genauso viel Anteil wie wir. Es ist daher nur gerecht, die Beute zu teilen.\n\nIch habe die Männer angewiesen, eine Truhe für Euch bereitzustellen. Nehmt Euch, was Ihr wollt.", sourceObjective = "Nehmt Euch Euren Anteil der Beute aus Durotans Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35252] = { id = 35252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chest Reward Tracking Quest" }
quests[35253] = { id = 35253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Thaelin Event Complete" }
quests[35254] = { id = 35254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung für das Licht", description = "Die Agenten der Finsternis lauern überall, um diese Welt mit Schatten zu überziehen. Koste es, was es wolle. Es ist unsere Aufgabe, das Licht zu schützen und den Kampf ausgeglichen zu halten.\n\nIhr verfügt über die notwendige Macht, um Teron'gors Dämonenschergen ein für alle Mal zu vernichten. Schickt sie zurück in den Wirbelnden Nether!", sourceObjective = "Tötet 15 Dämonen in Gul'rok.", completion = "Ich kann schon spüren, wie das Licht über die Finsternis triumphiert. Wir haben es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[35255] = { id = 35255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Genesauriers", description = "Jetzt habt Ihr nicht nur den Willen der Genesaurier, sondern auch genug Wasser und Samen, um eine ganze Armee zu züchten, Kommandant, von den Zwergenleben, die Ihr gerettet habt, ganz zu schweigen.\n\nDie Mission war ein voller Erfolg.\n\nIch werde den Zwergen helfen, ihren Betrieb hier herunterzufahren, und schauen, was ich dabei noch retten kann. Ihr könntet währenddessen das Artefakt zurück zu Maraad am Außenposten bringen.", sourceObjective = "Sprecht mit Verteidiger Maraad am Hochpass in Gorgrond.", completion = "Gut gemacht, Kommandant. Es haben schon viele Orcs versucht, die Macht des Genesauriers zu beherrschen. Aber so erfolgreich ist meines Wissens nach bis jetzt noch niemand gewesen.\n\nDamit sollte uns in den nächsten Tagen ein großer Vorteil zur Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35257] = { id = 35257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabene Macht", description = "Was für eine Macht könnte ein Dorf in einem Augenblick in Schutt und Asche legen? Die Jünger behaupten, es sei der Wille von Rukhmar.\n\nDas ist offensichtlich eine Lüge.\n\nSie haben nichts getan, um derartige Macht zu verdienen. Um die Wahrheit zu sagen, sind sie eher unabsichtlich in einem Erdloch darüber gestolpert.\n\nKommt und besucht mich an der Ausgrabungsstätte westlich von hier. Wir müssen ihre Technologie verstehen, wenn wir sie besiegen wollen.", sourceObjective = "Sprecht mit Dunkelseher Raastok in der Nähe der Apexisausgrabung.", completion = "Ah, da seid Ihr ja, gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[35258] = { id = 35258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Apexis", description = "Die Apexis sind längst verschwunden, doch ihr Erbe liegt in den uralten Kammern unter Arak begraben.\n\nLegionen schlafender Konstrukte, Kristalle voller Sonnenenergie, magische Techniken... Die Apexis haben ein Sammelsurium unglaublicher Macht hinterlassen, und die Jünger von Rukhmar haben damit begonnen, es auszugraben.\n\nBringt mir die Kerne der reaktivierten Konstrukte, die an der Ausgrabungsstätte patrouillieren. Diese Kristalle sind die Grundlage der Technologie der Apexis und der Schlüssel zur verheerenden Macht unseres Feindes.", sourceObjective = "Sammelt 5 Solarkerne von Apexiswächtern.", progress = "Die Apexis hatten alle Vorteile, und doch sind sie verschwunden. Was mag bloß passiert sein?", completion = "Ausgezeichnet. Damit können wir einen Anfang machen, sie zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35259] = { id = 35259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschwestern", description = "Als ich noch eine Wache der Himmelsnadel war, hatte ich die Aufgabe, die Schwestern Veoryx und Krashyx zu beschützen.\n\nSie waren Wunderkinder. In einem Alter, in dem die meisten Akolythen der Sonne kaum lesen können, beschworen die Schwestern bereits Familiare aus reinem Sonnenlicht, um in den frühen Morgenstunden Licht zum Studium ihrer Bücher zu haben.\n\nNun entwirren sie die Geheimnisse der Apexistechnologie. Bei ihren Ausgrabungen haben sie gerade zwei uralte Kammern freigelegt.\n\nBetretet diese Kammern und schaltet die Schwestern aus, bevor sie die schrecklichen Früchte ihrer Entdeckung ernten können.", sourceObjective = "Tötet Sonnenformerin Veoryx und Sonnenformerin Krashyx.", completion = "<Der Kern des schlafenden Konstrukts beginnt leise zu summen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35260] = { id = 35260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsscheu", description = "Diejenigen, die nicht beim Akrazversteck verbrannt sind, werden gezwungen, den Jüngern zu helfen, genau die Waffen auszugraben, die nun auf ihre Köpfe zielen.\n\nJeder, der zu entkommen versucht, wird vom Apexisgeschützturm des Aufsehers verdampft.\n\nMit diesen Abbildern werden sie nicht merken, dass jemand weg ist. Platziert eines davon in der Nähe eines versklavten Arbeiters und seht zu, wie eine perfekte Kopie entsteht. Die Kopie lässt ihr Original sogar im Schatten verschwinden, sodass es sicher entwischen kann!", sourceObjective = "Verwendet die Illusionsbildnisse, um Attrappen für 10 versklavte Ausgestoßene zu erstellen.", completion = "Täuschung ist eine mächtige Fähigkeit. Vergesst das nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35261] = { id = 35261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei!", description = "<Sonnenenergie durchströmt die schlafenden Konstrukte, ihre uralten Servomotoren erwachen überall um Euch herum zu neuem Leben. Es ist nun zu spät, sie abzuschalten.\n\nDraußen kläfft ein Aufseher der Arakkoa Befehle, die alle vom Summen eines Apexisstrahls beantwortet werden, der sich in den Berg schneidet.\n\nDieses Geschütz würde mit den Konstrukten kurzen Prozess machen... wenn Ihr die Kontrolle darüber übernehmen könnt.>", sourceObjective = "Nehmt die Apexissteuerung von Aufseher Akrath an Euch.", progress = "<Ein bequem aussehender Stuhl mit einer Fassung in der Armlehne.>", completion = "<Die Apexissteuerung rastet mit einem zufriedenstellenden Klicken ein. Es sieht aus, als diene der Stuhl dazu, die volle Kontrolle über das Geschütz zu übernehmen.\n\nBeim Durchsuchen der Polster findet Ihr ein paar Münzen, die kurz darauf in Euren Taschen verschwinden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35262] = { id = 35262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dienste von Rangari Kaalya", sourceObjective = "Kommandant, Eure Überlebensfähigkeiten sind unbestritten, aber es gibt noch vieles, das Ihr nicht wisst.\n\nIch würde Euch helfen. Ohne das Wissen der Rangari würde Draenor Eure Truppen verschlingen wie ein Goren die Felsen.\n\nWollt Ihr mein Angebot annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35264] = { id = 35264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Artefaktfragmente", progress = "Je mehr, desto besser!", completion = "Es muss Euch große Mühe bereitet haben, uns das zu bringen. Ihr habt Euch diese Belohnung verdient." }
quests[35265] = { id = 35265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual der Bindung", description = "Die Zeit ist gekommen, dass Ihr Euch dem Ritual der Bindung unterzieht, {name}.\n\nDieser uralte Schamanenritus wird schon seit langer Zeit vor meiner Geburt praktiziert. Es ist eine große Ehre, ausgewählt zu werden.\n\nViele Schamanen erleben im Verlauf des Rituals lebendige Elementarvisionen. Sie erleben diese Welt durch die elementaren Bande, die sie zusammenhalten.\n\nWenn Ihr bereit seid, mit dem Ritual zu beginnen, sprecht mit Kalandrios.", sourceObjective = "Sprecht mit Kalandrios, um das Ritual der Bindung zu beginnen.", completion = "<Scharfseher Drek'Thar hört genau zu, als Ihr von Eurer Vision sprecht>\n\nIch verstehe... dies sind wahrhaftig dunkle Tage. Cho'gall ist in das Herz des Oshu'gun eingedrungen und entzieht dem Naaru das Leben. Er will den Naaru vernichten und einen dunklen Gott der Leere an seine Stelle einsetzen.\n\nCho'gall muss aufgehalten werden. Kommt, wir müssen zum heiligen Berg, bevor es zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[35266] = { id = 35266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkter Charakter" }
quests[35267] = { id = 35267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Test" }
quests[35271] = { id = 35271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch den Kriegshymnenklan", description = "<Die Angriffspläne sind mit dicker, schwarzer Tinte auf das Pergament gekritzelt, das in grobes Leder gebunden ist.>\n\nAn alle vorgeschobenen Stellungen:\n\nDer Kriegsherr hat befohlen, dass sich die gesamte Vorhut auf einen Großangriff auf die Invasoren der Horde in unserem Land vorbereitet. Mehrere der entfernt gelegenen Außenposten der Vorhut haben Angriffspläne erhalten.\n\nBlut und Ruhm sollen unser sein, wenn wir die Eindringlinge der Horde unter unseren Füßen zerstampfen!\n\nDer Kriegsherr befiehlt und der Kriegshymnenklan folgt! Lok'tar ogar!", sourceObjective = "Stehlt die Angriffspläne des Kriegshymnenklans.", progress = "Was habt Ihr für mich?", completion = "<Blutwache Ehanes mustert die Angriffspläne.>\n\nHmm... verstehe. Gut, dass Ihr diese Angriffspläne beschafft habt. Mit diesen Plänen in unseren Händen werden wir mehr als vorbereitet sein und dem Angriff begegnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[35272] = { id = 35272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer von uns", description = "Diese Flattermänner haben mich gefangen genommen, als ich das Umland erkundet hab'.\n\nWir wollten hinter diesem Berg einen Außenposten für Euch errichten, um Euren Willen überall auf dem Kontinent zu verbreiten.\n\nAber wir kommen nicht voran.\n\nIch brauch Eure Hilfe, Kommandant. Könnt Ihr den Vogelleuten sagen, dass ich nix Böses von ihnen will, sodass ich Euch den Außenposten zeigen kann?", sourceObjective = "Sprecht mit Schattenweiser Iskar und überzeugt ihn, Schattenjäger Ukambe freizulassen.", progress = "Ihr habt mir den Allerwertesten gerettet, Kommandant.", completion = "Dank den Geistern, dass Ihr da seid! Sie hab'n meine Gebete erhört.", sourceObjectiveStatus = "unverified-source-field" }
quests[35273] = { id = 35273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heiße Stuhl", description = "<Apexiskonstrukte mit kriegerischen Absichten werden gleich aus diesen uralten Kammern hervortreten. Die Arakkoa werden sicher weitere Sonnenformer entsenden, um sie zu unterstützen.\n\nDie Steuerung und das Geschütz summen in sanftem Einklang.>", sourceObjective = "Übernehmt mit dem Aufseherstuhl die Kontrolle über den Apexisgeschützturm und tötet 20 Apexiszerstörer und 30 Sonnenformer der Jünger.", completion = "Ahh, ganze Arbeit. Selbst in meinem Zustand konnte ich das Gemetzel von hier aus spüren.\n\nDas muss ein ordentliches Feuerwerk gewesen sein, Krah-Ha-Ha.", sourceObjectiveStatus = "unverified-source-field" }
quests[35274] = { id = 35274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer von uns", description = "Diese armseligen Kreaturen haben mich gefangen genommen, als ich die Gegend erkundet habe. Jetzt da Ihr hier seid, Kommandant, könnten wir wirklich Eure Hilfe im Stützpunkt gebrauchen.\n\nOh, und könntet Ihr vielleicht Eure... Freunde... überzeugen, mich frei zu lassen?\n\nSie, äh... wollen mich nicht gehen lassen.", sourceObjective = "Sprecht mit Schattenweiser Iskar und überzeugt ihn, Jasper Teufel freizulassen.", completion = "Könnten wir diesen äh...kleinen Zwischenfall vielleicht einfach vergessen, Kommandant?\n\nBodrick und die anderen Agenten würden mir das ewig vorhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35275] = { id = 35275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppeninspektion", description = "Axtfall is' nicht weit weg von hier.\n\nIch werd' die Stelle auf Eurer Karte markieren, wir treffen uns dort.", sourceObjective = "Sprecht mit Schattenjäger Ukambe in Axtfall.", completion = "Unsere Leben für Euren Willen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35276] = { id = 35276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppeninspektion", description = "Südhafen befindet sich nicht weit von hier im Südwesten.\n\nAber wir haben keine Zeit zum Plaudern. Wir treffen uns dann dort, Kommandant.", sourceObjective = "Sprecht mit Jasper Teufel in Südhafen.", completion = "Ich hoffe, dass Ihr rundum zufrieden seid. Das war wirklich harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35277] = { id = 35277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Befehle, Kommandant?", description = "Kommandant, unsere Lage ist... bedauernswert.\n\nIn wenigen Tagen werden unsere Vorräte zur Neige gehen – wenn wir dann überhaupt noch irgendwelche Truppen haben.\n\nEs gibt gerade noch genug Material, um ein Gasthaus oder einen Handelsposten zu errichten.\n\nMithilfe des Gasthauses könnten wir hier frische Truppen stationieren. Der Handelsposten dagegen würde uns potenzielle Nachschubrouten mit den Ausgestoßenen in der Nähe zur Verfügung stellen.\n\nIch habe Euch Gazlowes Baupläne auf den Zeichentisch gelegt. Wir erwarten Eure Befehle.", sourceObjective = "Werft einen Blick auf den Zeichentisch und entscheidet, welches Gebäude des Außenpostens Ihr errichten wollt.", completion = "Wie Ihr befehlt.\n\nFür die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[35279] = { id = 35279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 1" }
quests[35280] = { id = 35280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schattenmondschatz 2" }
