quests[35284] = { id = 35284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handelsposten" }
quests[35285] = { id = 35285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dem Hotrod!", description = "Fräulein Kimzee ist ein zäher Knochen, aber das Quetschpfeifenkap ist zu gefährlich für sie allein. Es wäre eine Katastrophe für die Moral, wenn unser Boss infiziert werden würde.\n\nIch muss diese Mannschaftsmitglieder zurück in die Werkstatt bringen, also müsst Ihr dafür sorgen, dass mit ihr alles in Ordnung ist.\n\nDas Zuhause ihres Onkels ist der Turm auf der gegenüberliegenden Seite des Ölfelds. Ich denke, Ihr solltet dort nach ihr suchen.", sourceObjective = "Sucht nach Kimzee Quetschpfeife am Quetschpfeifenkap.", completion = "Ich habe gute und schlechte Nachrichten.\n\nDie gute Nachricht ist, dass mein Onkel lebt! Die schlechte ist, dass sein Bein verletzt ist und wir von den Infizierten umzingelt sind! Mit meinem kaputten Hotrod können wir ihn nicht da rausholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35286] = { id = 35286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Befehle, Kommandant?", description = "Kommandant {name}, es ist mir eine Ehre.\n\nWir können hier kaum noch durchhalten. Wir haben bestenfalls noch Vorräte für eine Woche – wenn wir dann überhaupt noch irgendwelche Truppen haben.\n\nEs gibt gerade noch genug Material, um ein Gasthaus oder einen Handelsposten zu errichten.\n\nMithilfe des Gasthauses könnten wir hier Verstärkung stationieren. Der Handelsposten dagegen würde uns Nachschubrouten mit den Ausgestoßenen in der Nähe bieten.\n\nZum Bau benötigen wir Eure Genehmigung, Kommandant. Die Wahl liegt ganz bei Euch.", sourceObjective = "Werft einen Blick auf den Zeichentisch und entscheidet, welches Gebäude des Außenpostens Ihr errichten wollt.", completion = "Dem Licht sei dank, dass Ihr da seid. Ich dachte schon, wir müssten einen Kurier senden, um von Eurer Entscheidung zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35287] = { id = 35287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragefire Chasm Reward Quest" }
