quests[35292] = { id = 35292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ang'kra, die Alchemistin", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35293] = { id = 35293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Freunde", description = "Admiral Taylor erhielt den Befehl, weiter im Landesinneren eine Garnison zu errichten, während wir Eure Garnison im Schattenmondtal errichtet haben. Er hat sich nur ein kurzes Stück nördlich von hier niedergelassen.\n\nWir beide könnten dorthin reisen und uns einige Vorräte borgen, um die Zeit zu überbrücken, bis unsere nächste Lieferung eintrifft.\n\nWas meint Ihr, Kommandant? Ich bin sicher, der Admiral wäre hocherfreut, Euch wiederzusehen.", sourceObjective = "Sprecht mit Jasper Teufel in der Garnison von Admiral Taylor.", completion = "Was in des Königs Namen ist hier geschehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35294] = { id = 35294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jasper in Bewegung" }
quests[35295] = { id = 35295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her damit!", description = "Ich hab beim Späh'n noch was rausgefund'n, Boss.\n\nDie Allianz hat 'ne Garnison gleich da hinten. Und da is' 'ne ganze Weile keiner rein- und rausgegang'n.\n\nIs' 'ne super Gelegenheit, um den Laden zu plündern un' sich die Taschen vollzumach'n, Kommandant.\n\nWas meint Ihr? Können wir doch zusammen mach'n.", sourceObjective = "Sprecht mit Schattenjäger Ukambe in der Garnison von Admiral Taylor.", completion = "Alle sin' tot, Mann. Was war das?", sourceObjectiveStatus = "unverified-source-field" }
quests[35296] = { id = 35296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchter Garten", description = "Der verlassene Minenschacht ist von Goren überrannt worden! Sie scheinen die Befehle eines großen Anführers tief unten in der Mine zu befolgen. Wenn ihr ihn ausschalten könnt, werden sich die anderen vielleicht zurückziehen.\n\nUnd wenn Ihr erst die Goren erledigt habt, könnten wir diese Mine wieder in Gang bringen!Ihr erlernt:", sourceObjective = "Tötet Steinzahn in der Garnisonsmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[35297] = { id = 35297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Army Pushed" }
quests[35298] = { id = 35298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen los", description = "Also schön, {name}, wir haben so viele gerettet, wie wir konnten, aber jetzt müssen wir sicherstellen, dass sich diese Katastrophe nicht noch weiter ausbreitet.\n\nDie Feuerbomben sind verkabelt und bereit.\n\nKimzee hat gerade die Arbeiten an der Flugmaschine abgeschlossen, also können wir zur Werkstatt zurückfliegen, sobald wir hier fertig sind.\n\nIhr habt die ganze harte Arbeit geleistet, also finde ich, Ihr solltet die Ehre haben, die Bomben zu zünden.", sourceObjective = "Aktiviert den Feuerbombenzünder und entkommt dann mit Kimzees Flugmaschine.", completion = "{name}, Ihr habt fantastische Arbeit geleistet.\n\nAlle hier in der Werkstatt stehen tief in Eurer Schuld nach allem, was Ihr für uns getan habt.\n\nHier, ich möchte Euch noch eine Kleinigkeit geben. Betrachtet sie als ein Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35303] = { id = 35303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wailing Caverns Reward Quest" }
