quests[35317] = { id = 35317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dunkle Herz des Oshu'gun", description = "Wir sind jetzt ganz nah an der inneren Kammer, {name}. Hier erwartet uns die Wahrheit hinter dem Bösen.\n\nIch kann meinen Geist in die Kammer entsenden, um Euch den Weg zu zeigen. Aber es wird Eure Aufgabe sein, das Böse dort zu besiegen.\n\nMögen die Winde von Kalandrios Euren Arm führen, die Weisheit von Aborius Eure Talente befördern und die Flamme von Incineratus Eure Feinde verbrennen.\n\nUnd möge das Andenken von Gordawg Euer Schild sein.", sourceObjective = "Betretet das Sanktum des Naaru.", completion = "Ihr habt Großes geleistet, {name}.\n\nDurch die Vernichtung des Leerengottes Dezimatus konnte die Zerstörung des Tales verhindert werden. Und auch die Bedrohung durch die Fahlen ist vorerst vorüber.\n\nDer Verlust von Gordawg wird in ganz Nagrand zu spüren sein. Aber eines Tages wird ein neuer Erdzorn den Thron der Elemente besteigen und damit das Gleichgewicht wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35318] = { id = 35318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu'shan Palace Reward Quest" }
