quests[35320] = { id = 35320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shado-Pan Monastery Reward Quest" }
quests[35321] = { id = 35321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu'shan Palace Reward Quest" }
quests[35322] = { id = 35322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Menschen", description = "Alle hier sind... tot.\n\nDieser Architektengeist will nich' gegen uns kämpf'n. Selbst im Tod will er nur arbeiten. Vielleicht können wir den Schleier, der ihm den Verstand benebelt, lüften und herausfinden, was gescheh'n is'.\n\nIch wette, einer der spektralen Arbeiter hat einen seiner Pläne. Den könnten wir ihm zeigen, um seinen Kopf klar zu krieg'n.", sourceObjective = "Besorgt Bryan Finns Bauplan von den spektralen Arbeitern.", progress = "Einen meiner Baupläne würde ich unter Tausenden erkennen.", completion = "Danke, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[35323] = { id = 35323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormstout Brewery Reward Quest" }
quests[35324] = { id = 35324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormstout Brewery Reward Quest" }
quests[35325] = { id = 35325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of the Jade Serpent Reward Quest" }
quests[35327] = { id = 35327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of the Jade Serpent Reward Quest" }
quests[35329] = { id = 35329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Menschen", description = "S-Sie sind Geister! Allesamt!\n\nBryan war einer meiner besten Freunde. Irgendetwas hat seinen Geist benebelt. Wir müssen ihn wachrütteln und die Ursache aufklären!\n\nEr war immer wie besessen von seiner Arbeit. Vielleicht besinnt er sich, wenn wir ihm einen seiner Baupläne zeigen. Einer der spektralen Arbeiter könnte einen davon haben.", sourceObjective = "Besorgt Bryan Finns Bauplan von den spektralen Arbeitern.", progress = "Einen meiner Baupläne würde ich unter Tausenden erkennen.", completion = "Danke, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[35330] = { id = 35330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual der Bindung", description = "Es ist an der Zeit, dass Ihr Euch dem Ritual der Bindung unterzieht, {name}. Ich werde hier warten, während Ihr mit Kalandrios sprecht, um mit dem Ritus zu beginnen.\n\nIm Verlauf des Rituals werdet Ihr Visionen der Elemente erleben. Kehrt zu mir zurück, wenn das Ritual abgeschlossen ist, dann werden wir uns weiter unterhalten.", sourceObjective = "Sprecht mit Kalandrios, um das Ritual der Bindung zu beginnen.", completion = "<Verteidiger Nobundo hört genau zu, als Ihr von der Vision erzählt.>\n\nDiese Bilder, die Ihr gesehen habt, sind in der Tat bedrückend, {name}. Wenn Cho'gall weiterhin dem Naaru sein Licht entzieht, wird K'ure sterben und anstelle des Naaru wird ein Leerengott entstehen. Leerengötter sind schreckliche Kreaturen, deren einziger Lebenszweck die Zerstörung ist!\n\nWir müssen umgehend zum Oshu'gun reisen, wenn wir der Bedrohung durch Cho'gall ein Ende bereiten wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35331] = { id = 35331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz am Thron", description = "Ich war weit entfernt von hier in Talador, als die Stimme nach mir rief.\n\nIch sah mich um, doch war ich alleine. Wieder hörte ich die Stimme wie einen Windhauch, der durch meinen Verstand wehte.\n\n\"Ihr werdet am Thron gebraucht\", flüsterte sie.\n\nDie Stimme bezeichnete sich selbst als Kalandrios und führte mich zu diesem Ort.\n\nIch war noch nie zuvor hier, diese Zorne hatte ich noch nie mit eigenen Augen gesehen. Und doch fühlt es sich seltsam vertraut an, als wäre es vor langer Zeit in einem längst vergessenen Traum passiert.\n\nWir sollten die Zorne begrüßen und uns anhören, was sie zu sagen haben.", sourceObjective = "Haltet mit den Zornen am Thron der Elemente Zwiesprache.", completion = "Ich bin nicht sicher, was ich davon halten soll.\n\nDie Elemente befinden sich nicht mehr im Gleichgewicht? Der große Zorn Gordawg ist verschwunden und muss wiedergefunden werden?\n\nDie Zorne scheinen ehrbar zu sein, und tief in meiner Seele klingen ihre Worte wahr.\n\nIch glaube, wir sollten sie unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35332] = { id = 35332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobundo schickt Kunde", description = "Man bittet um Eure Anwesenheit am Thron der Elemente, {name}.\n\nVerteidiger Nobundo hat im Wind den Ruf der Zorne vernommen und sich daraufhin aufgemacht, mit den Elementen Zwiesprache zu halten.\n\nIch kenne die Absichten der Zorne nicht, aber von den Orcs werden sie als mächtige und ehrenvolle Geister verehrt.", sourceObjective = "Findet Verteidiger Nobundo beim Thron der Elemente.", completion = "Gut, dass Ihr sicher hier angekommen seid.\n\nKommt, es gibt hier viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[35333] = { id = 35333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf die Elemente", description = "Und auch in diesem Augenblick lässt mir Kalandrios eine Botschaft zukommen.\n\n\"<Der Held/Die Heldin> von Azeroth muss sich mit den Elementen des Plateaus abstimmen.\"\n\nAuf dem Elementarplateau befinden sich vier große Säulen aus lebendem Stein. Wenn Ihr Eure Hand auf die Säulen legt, wird Eure Seele auf die Elemente abgestimmt.\n\nWährend Ihr Euch zu dem Plateau begebt, werde ich derweil weiter mit den großen Zornen kommunizieren und versuchen, ihren Willen zu verstehen.", sourceObjective = "Stimmt Euch auf die vier Elementarsäulen ein.", completion = "Ich kann das Feuer in Euren Augen und eine neue Kraft in Euren Bewegungen sehen, {name}.\n\nWenn Kalandrios die Wahrheit sagt, habt Ihr Eure Lebensenergie auf allen Elementarkräfte Draenors abgestimmt.\n\nDie Stimme sagt, dass Ihr jetzt für das Ritual der Bindung bereit seid.\n\nSprecht mich an, wenn Eure Aufgabe auf dem Plateau beendet ist. Dann werden wir uns erneut unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35334] = { id = 35334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Varashas Ei" }
quests[35335] = { id = 35335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bashiok" }
quests[35337] = { id = 35337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stampfende Geräusche", description = "Kommandant, die Rangari und ich haben gerade die Vorteile verschiedener \"Jagdmethoden\" erörtert.\n\nIch konnte ihr versichern, dass der SI:7 für jede Situation gewappnet ist – auch in der Wildnis.\n\nSie aber glaubt, dass wir in \"ihrem Land\" nicht in der Lage sind, Beute zu machen.\n\nWir sollten sie davon überzeugen, dass sie sich irrt. Gehen wir ein paar Grollhufe jagen.", sourceObjective = "Sammelt 12 Paar Lederhautohren von Lederhautgrollhufen.", progress = "Unglaublich, wie arrogant diese Rangari sein können.", completion = "Zwölf Paare also? Das ist ziemlich gut, Kommandant.\n\nHm, ich glaube, so viele habe ich nicht erbeuten können. Ich hab... ungefähr ein Dutzend Ohrenpaare. Tja...", sourceObjectiveStatus = "unverified-source-field" }
quests[35338] = { id = 35338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdwettstreit", description = "Kia und ich befinden uns in einem Wettstreit darüber, wer sich besser auf das Jagdhandwerk versteht: SI:7 oder Rangari.\n\nWollt Ihr vielleicht in diesen Wettkampf einsteigen, Kommandant?\n\nIch habe mir die wilden, majestätischen Talbuks als bevorzuge Beute ausgesucht. Wie alle Bewohner Draenors wissen, repräsentieren sie die ganze Pracht von Nagrand.", sourceObjective = "Sammelt 24 Brisenschreiterhörner von Brisenschreitertalbuks.", progress = "Diese dummdreiste Fremde glaubt doch wirklich, sie kann einfach hier auftauchen und mich in meinem eigenen Land übertreffen?!\n\nOh... Tut mir leid, Kommandant. Das gilt natürlich nicht für Euch.", completion = "Vierundzwanzig also? Gute Arbeit.\n\nIch habe fünfzig mitgebracht.\n\nIch werde jemanden schicken, um das Fleisch abzuholen. Wir wollen ja nichts umkommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35339] = { id = 35339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen zum Abschied", description = "Keine Ahnung, was passiert ist. Meine Mannschaft und ich müssen zu den ersten Opfern gehört haben.\n\nMeine Frau, die Gastwirtin, ist in einer ähnlichen Starre wie ich sie hatte, als Ihr mich gefunden habt. Ich kann es spüren. Auch andere sind betroffen.\n\nBitte, gewährt den Dorfbewohnern Frieden und zeigt ihre Essenzen meiner Frau. Das sollte sie aus diesem kalten Abgrund zurückholen.", sourceObjective = "Sammelt 6 spektrale Essenzen von den ruhelosen Geistern in der Garnison und verwendet sie, um Alice Finn über ihr Schicksal aufzuklären.", progress = "Ich fühle mich so... benommen... Was ist geschehen? Wer seid Ihr?", completion = "Wir sind... tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[35340] = { id = 35340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist hier passiert?", description = "Dieser Architektengeist will nich' gegen uns kämpf'n. Vielleicht können wir den Schleier über seinem Verstand lüft'n und herausfinden, was gescheh'n is'.\n\nIch wette, einer der untoten Bauern hat einen seiner Pläne oder irgendwas, um seinen Kopf klar zu krieg'n.\n\nKönnte 'n Versuch wert sein.", sourceObjective = "Sucht nach einem von Bryan Finns Plänen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35341] = { id = 35341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlaufangebot von Gronnjäger Rokash", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "Ihr habt Euch als mächtiger als meine früheren Anführer bewiesen. Ich stehe Euch zu Diensten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35342] = { id = 35342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mysteriöse Fläschchen", description = "Die wirbelnde Flüssigkeit in dem Fläschchen besitzt eindeutig ein starkes alchemistisches Potential, doch mit Euren Fähigkeiten vermögt Ihr es nicht zu ergründen.\n\nEiner der Dorfbewohner von Abendruh in Eurer Garnison scheint in der Alchemie bewandert zu sein. Womöglich kann er Euch weiterhelfen.", sourceObjective = "Sprecht mit Aenir in Eurer Garnison.\n\nBereitgestellter Gegenstand:", completion = "Ah, wie ich sehe, habt Ihr ein Erzeugnis der Alchemie von Draenor gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35343] = { id = 35343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die junge Alchemistin", description = "Ich habe von meiner Tante etwas Alchemie gelernt. Wenn Ihr aber mehr wissen wollt, solltet Ihr mit meiner Cousine Abatha sprechen. Sie war bei meiner Tante in der Lehre, bevor diese starb.\n\nAbatha lebt mit ihrem Vater und ihrer Schwester in der Nähe des Grünen Morastes.", sourceObjective = "Findet Abatha beim Grünen Morast.", completion = "Bitte. Helft mir. Ich muss meinen Vater finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35344] = { id = 35344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Vater", description = "Ich würde Euch gern bei Euren Fragen zur Alchemie helfen, aber ich mache mir gerade solche Sorgen um meinen Vater.\n\nEr wollte unten am Fluss jagen, aber er ist jetzt schon so lange fort. Ich muss auf Lumiel aufpassen. Würdet Ihr Vater bitte suchen?", sourceObjective = "Findet Telos im Grünen Morast.", completion = "Vielen Dank, Fremder. Ich glaube, die Messerklauen waren nicht erfreut, dass ich die gleiche Beute jagte wie sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[35345] = { id = 35345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schockierende Hilfe", description = "Es ist nicht leicht, meine Familie zu versorgen, seit meine Frau verstorben ist. Ich habe mich übernommen, als ich diese Bestellung Schockschuppen annahm.\n\nIch werde niemals genug Aale fangen, um ihr rechtzeitig nachzukommen.", sourceObjective = "Sammelt 100 Schockschuppen von Schockschuppenaalen.", progress = "Ich danke Euch sehr, dass Ihr meinen Vater gefunden habt.", completion = "Das habt Ihr für meine Familie getan? Nachdem Ihr unseren Vater gerettet habt? Ich danke Euch, {name}.\n\nIhr habt Fragen zur Alchemie von Draenor? Ich werde mein Wissen mit Euch teilen, so gut ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[35346] = { id = 35346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abatha die Alchemistin", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[35347] = { id = 35347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ogerbeute 000" }
