quests[35350] = { id = 35350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin der Grollhufe", description = "Laara sagte mir, dass Banthar in der Nähe ist! Oder vielmehr, dass sie hier immer noch am Leben sei. Wisst Ihr, was ich meine?\n\nDas ist unsere Gelegenheit, Kommandant. Wir können eine jüngere und mächtigere Ausgabe von Banthar erlegen und diesen Rangari eine Lektion erteilen.\n\nWir werden Laara zeigen, wie echte Profis arbeiten.", sourceObjective = "Besorgt das Horn von Banthar.", progress = "Das Horn von Banthar. Hemet würde alles dafür geben, eine solch mächtige Bestie erlegen zu dürfen.", completion = "Ein Triumph, Kommandant. Ihr habt uns alle stolz gemacht.", sourceObjectiveStatus = "unverified-source-field" }
